import { useCallback, useEffect } from 'react';
import { useDispatch } from 'react-redux';

import type OpenFin from '@openfin/core';

import { createLogger } from '@common/utils/logger';

import { i18next, initI18next, Resource } from '@common/api/i18next';

import { getCurrentSync } from '@client-platform/api';

initI18next();

const logger = createLogger('usePlatformLocalization');

/**
 * Fetch and apply selected language and translation dictionaries.
 * @param identity the platform identity.
 */
export const usePlatformLocalization = (identity?: OpenFin.Identity) => {
    const dispatch = useDispatch();

    const fetchAndUpdateLanguage = useCallback(async () => {
        // eslint-disable-next-line no-underscore-dangle
        const { currentLanguage, resources } = await getCurrentSync()
            ._getLanguageResources()
            .catch((error) => {
                logger.warn('fetchAndUpdateLanguage', `Error fetching language resources, ignoring.`, {
                    error,
                    identity
                });
                return { currentLanguage: 'en-US', resources: {} as Resource };
            });
        Object.keys(resources).forEach((languageCode) => {
            // Update dictionary with resources fetched from platform provider. Need this to apply corrections.
            i18next.addResourceBundle(languageCode, 'translation', resources[languageCode].translation, true, true);
        });
        // only call after adding overrides to ensure react effects listening to language change receive updated translations
        i18next.changeLanguage(currentLanguage);
    }, [identity]);

    useEffect(() => {
        if (!identity || !fin) return;

        const platform = fin.Platform.wrapSync(identity);
        platform.on('platform-api-ready', fetchAndUpdateLanguage);

        return () => {
            platform.removeListener('platform-api-ready', fetchAndUpdateLanguage);
        };
    }, [dispatch, identity, fetchAndUpdateLanguage]);
};
