import type OpenFin from '@openfin/core';

import { finUUID, isFin } from './env';

export enum ApplicationUUID {
    /**
     * The UUID of workspace.
     * Home is a part of this application.
     */
    Workspace = 'openfin-workspace',
    OldWorkspace = 'openfin-browser'
}

export interface ApplicationEvent {
    viewIdentity?: OpenFin.Identity;
    name?: string;
    uuid?: string;
}

export type ApplicationListener = (ev: ApplicationEvent) => void;

export enum LaunchModeType {
    FinProtocol = 'fin-protocol'
}

export type ApplicationInfoExtended = OpenFin.ApplicationInfo & {
    initialOptions: OpenFin.ApplicationInfo['initialOptions'] & { userAppConfigArgs: any };
};

const currentOFAppIdentity = { uuid: finUUID };
const workspaceOFAppIdentity = { uuid: ApplicationUUID.Workspace };

const getOFApplication = (identity: OpenFin.ApplicationIdentity) => {
    if (!isFin) {
        throw new Error('getApplication cannot be used in a non OpenFin env. Avoid using this during pre-rendering.');
    }
    return fin.Application.wrapSync(identity);
};

export const getCurrentOFApplication = () => getOFApplication(currentOFAppIdentity);

export const getWorkspaceOFApplication = () => getOFApplication(workspaceOFAppIdentity);

let manifestPromise: Promise<OpenFin.Manifest> | null = null;

/**
 * Gets the application manifest, caching the result after the first call.
 * The manifest never changes during the application lifecycle, so this avoids redundant async calls.
 * Uses promise-based caching to prevent race conditions when multiple calls occur before the first completes.
 * @returns A Promise resolving to the application manifest
 */
export const getCachedManifest = async (): Promise<OpenFin.Manifest> => {
    if (!manifestPromise) {
        manifestPromise = fin.Application.getCurrentSync().getManifest();
    }
    return manifestPromise;
};

let appInfoPromise: Promise<OpenFin.ApplicationInfo> | null = null;

/**
 * Gets application info, caching the result after the first call.
 * Application info (manifestUrl, licenseKey, runtime version, etc.) never changes
 * during the application lifecycle. Multiple callers (overrides, sentry, analytics)
 * share a single IPC call.
 */
export const getCachedAppInfo = async (): Promise<OpenFin.ApplicationInfo> => {
    if (!appInfoPromise) {
        appInfoPromise = fin.Application.getCurrentSync().getInfo();
    }
    return appInfoPromise;
};
