export const workspacePerformancePrefix = 'of-workspace-';

type WorkspacePerformanceMarks =
    | 'home-registration'
    | 'dock-registration'
    | 'store-registration'
    | 'home-show'
    | 'dock-show'
    | 'store-show'
    | 'workspace-app-started'
    | 'home-window-initialized'
    | 'dock-window-initialized'
    | 'store-window-initialized';

type BrowserWindowPerformanceMarks = string;

type PerformanceMarks = WorkspacePerformanceMarks | BrowserWindowPerformanceMarks;

/**
 * @classdesc
 * WorkspacePerformance is a class that provides a set of methods to measure performance of workspace
 *
 */
class WorkspacePerformance {
    public mark(markName: PerformanceMarks) {
        performance.mark(`${workspacePerformancePrefix}${markName}`);
    }
    public markStart(markName: PerformanceMarks) {
        performance.mark(`${workspacePerformancePrefix}${markName}-start`);
    }

    public markEnd(markName: PerformanceMarks) {
        performance.mark(`${workspacePerformancePrefix}${markName}-end`);
    }

    public markEndAndMeasure(markName: PerformanceMarks) {
        performance.mark(`${workspacePerformancePrefix}${markName}-end`);
        try {
            return performance.measure(
                `${workspacePerformancePrefix}${markName}`,
                `${workspacePerformancePrefix}${markName}-start`,
                `${workspacePerformancePrefix}${markName}-end`
            );
        } catch (e) {
            if (typeof process !== undefined && process?.env?.NODE_ENV !== 'production') {
                console.error(`Error measuring ${markName}`, e);
            }
        }
    }

    public markAndMeasure(markName: PerformanceMarks, measureAgainst: PerformanceMarks) {
        performance.mark(`${workspacePerformancePrefix}${markName}`);
        try {
            return performance.measure(
                `${workspacePerformancePrefix}${markName}-measure`,
                `${workspacePerformancePrefix}${measureAgainst}-start`,
                `${workspacePerformancePrefix}${markName}`
            );
        } catch (e) {
            if (typeof process !== undefined && process?.env?.NODE_ENV !== 'production') {
                console.error(`Error measuring ${markName}`, e);
            }
        }
    }

    public reportWorkspacePerformanceEntries(): PerformanceEntry[] {
        const entries = performance.getEntriesByType('measure');
        return entries.filter((entry) => entry.name.startsWith(workspacePerformancePrefix));
    }

    public reportWorkspacePerformance(): { name: string; duration: number }[] {
        return this.reportWorkspacePerformanceEntries().map((entry) => ({
            name: entry.name.replace(`${workspacePerformancePrefix}`, '').replace('-measure', ''),
            duration: entry.duration
        }));
    }
}

const workspacePerformance = new WorkspacePerformance();

export default workspacePerformance;
