import type OpenFin from '@openfin/core';

import { createLogger } from '@common/utils/logger';
import { currentOFIdentity, getBrowserWindows, getModalWindows, WindowName } from '@common/utils/window';

import { BrowserChannelAction, getChannelClient } from '@common/api/protocol/browser';
import { getNotificationsSyncChannelClient, NotificationsChannelAction } from '@common/api/protocol/notifications';
import { getChannelClient as getWorkspaceChannelClient } from '@common/api/protocol/workspace';
import {
    getWorkspacePlatformChannelClient,
    WorkspacePlatformChannelAction
} from '@common/api/protocol/workspace-platform';
import { mapGeneratedPalettesToLegacyPalettes } from '@common/api/theme-migration';
import type { CustomThemes, GeneratedPalettes, NotificationIndicatorColorsParsed } from '@common/api/theming';

import { getThemeStorageController } from '@client-platform/api/controllers/theme-storage-controller-store';

import { ColorSchemeOptionType, LegacyNotificationsThemeSet, ThemeApi } from '@client-platform/shapes';

const log = createLogger('theming');

export const getThemingApi = (identity: OpenFin.ApplicationIdentity): ThemeApi => ({
    getThemes: async (): Promise<CustomThemes | null> => {
        const client = await getWorkspacePlatformChannelClient(identity);

        return client.dispatch(WorkspacePlatformChannelAction.GetThemes, undefined);
    },
    getGeneratedPalettes: async (): Promise<GeneratedPalettes> => {
        const client = await getWorkspacePlatformChannelClient(identity);

        return client.dispatch(WorkspacePlatformChannelAction.GetGeneratedPalettes, undefined);
    },
    getThemePaletteSheet: async (): Promise<string> => {
        const client = await getWorkspacePlatformChannelClient(identity);

        return client.dispatch(WorkspacePlatformChannelAction.GetThemePaletteSheet, undefined);
    },
    setSelectedScheme: async (newScheme: ColorSchemeOptionType): Promise<void> => {
        const client = await getWorkspacePlatformChannelClient(identity);

        return client.dispatch(WorkspacePlatformChannelAction.SetSelectedScheme, newScheme);
    },
    getSelectedScheme: async (): Promise<ColorSchemeOptionType> => {
        const client = await getWorkspacePlatformChannelClient(identity);

        return client.dispatch(WorkspacePlatformChannelAction.GetSelectedScheme, undefined);
    },
    getNotificationIndicatorColorsInternal: async (): Promise<NotificationIndicatorColorsParsed> => {
        const client = await getWorkspacePlatformChannelClient(identity);

        return client.dispatch(WorkspacePlatformChannelAction.GetNotificationIndicatorColorsInternal, undefined);
    },
    getIsLegacySinglePaletteTheme: async (): Promise<boolean> => {
        const client = await getWorkspacePlatformChannelClient(identity);

        return client.dispatch(WorkspacePlatformChannelAction.GetIsLegacySinglePaletteTheme, undefined);
    },
    getLegacyNotificationsThemeInternal: async (): Promise<LegacyNotificationsThemeSet | null> => {
        const client = await getWorkspacePlatformChannelClient(identity);

        return client.dispatch(WorkspacePlatformChannelAction.GetLegacyNotificationsThemeInternal, undefined);
    }
});

const dispatchSchemeToDock3 = async (scheme: ColorSchemeOptionType) => {
    const client = await getChannelClient({ name: 'dock3', uuid: currentOFIdentity.uuid });
    await client.dispatch(BrowserChannelAction.SetSelectedScheme, scheme);
};

const dispatchSchemeToWorkspaceProvider = async (scheme: ColorSchemeOptionType) => {
    const client = await getWorkspaceChannelClient();
    await client.dispatch('set-selected-scheme', scheme);
};

export const dispatchThemeToWorkspaceProvider = async (themeData: {
    themePaletteSheet: string;
    selectedScheme: ColorSchemeOptionType;
    themePalette: { light: string; dark: string };
}) => {
    log.debug('dispatchThemeToWorkspaceProvider called', 'themeData', { themeData });

    const client = await getWorkspaceChannelClient();
    await client.dispatch('initialize-theme', themeData);
};

const dispatchSchemeToNotifications = async (scheme: ColorSchemeOptionType) => {
    const channelClient = await getNotificationsSyncChannelClient();
    await channelClient.dispatch(NotificationsChannelAction.UpdatePlatformThemeScheme, { scheme });
};

const dispatchSchemeToBrowserWindows = async (scheme: ColorSchemeOptionType) => {
    const browserWindows = await getBrowserWindows();

    return Promise.all(
        browserWindows.map(async (browser) => {
            const client = await getChannelClient(browser.identity);
            await client.dispatch(BrowserChannelAction.SetSelectedScheme, scheme);
        })
    );
};

const dispatchSchemeToModalWindows = async (scheme: ColorSchemeOptionType) => {
    const modalWindows = await getModalWindows();

    return Promise.all(
        modalWindows.map(async (modal) => {
            const client = await getChannelClient(modal.identity);
            await client.dispatch(BrowserChannelAction.SetSelectedScheme, scheme);
        })
    );
};

const dispatchSchemeToFindInPageModal = async (scheme: ColorSchemeOptionType) => {
    const views = await fin.Application.getCurrentSync().getViews();
    const findInPageViews = views.filter((view) => view.identity.name.startsWith(WindowName.FindInPageViewPrefix));

    return Promise.all(
        findInPageViews.map(async (view) => {
            const client = await getChannelClient(view.identity, 'theme-change-listener');
            await client.dispatch(BrowserChannelAction.SetSelectedScheme, scheme);
        })
    );
};

export const setSelectedScheme = async (schemeType: ColorSchemeOptionType): Promise<void> => {
    try {
        const themeController = getThemeStorageController();
        if (themeController.getIsLegacySinglePaletteTheme()) {
            log.warn(
                'setSelectedScheme: scheme switching is disabled for legacy single-palette themes',
                'use new theme format to enable scheme switching'
            );
            return;
        }
        themeController.setScheme(schemeType);
        await Promise.all([
            themeController.synchronizeWorkspaceStorage(),
            // The below dispatches can be removed once all workspace pages
            // are migrated to StorageThemeProvider
            dispatchSchemeToNotifications(schemeType),
            dispatchSchemeToBrowserWindows(schemeType),
            dispatchSchemeToModalWindows(schemeType),
            dispatchSchemeToFindInPageModal(schemeType),
            dispatchSchemeToWorkspaceProvider(schemeType),
            dispatchSchemeToDock3(schemeType)
        ]);
    } catch (error) {
        console.error('failed to set the selected scheme: ', error);
    }
};

export const getSelectedScheme = (): ColorSchemeOptionType | null | undefined => {
    try {
        const selectedScheme = getThemeStorageController().getScheme();
        return selectedScheme as ColorSchemeOptionType;
    } catch (error) {
        console.error('failed to get the selected scheme: ', error);
    }
};

/** @internal */
export const getIsLegacySinglePaletteTheme = (): boolean => {
    try {
        return getThemeStorageController().getIsLegacySinglePaletteTheme();
    } catch (error) {
        console.error('failed to get legacy single-palette theme flag: ', error);
        return false;
    }
};

export const getThemePaletteSheet = (): string | undefined => {
    try {
        const themePaletteSheet = getThemeStorageController().getThemePaletteSheet();
        return themePaletteSheet;
    } catch (error) {
        console.error('failed to get the theme palette sheet: ', error);
    }
};

// Theme mapping functions are shared with common (used by the legacy theme
// fallback path in workspace apps). Re-exported here for backward compatibility
// with existing consumers in client-api-platform.
export {
    assignIfDefined,
    mapGeneratedPalettesToLegacyPalettes,
    mapLegacyBrandIcons,
    mapLegacyThemeToCustomTheme
} from '@common/api/theme-migration';

/**
 * Builds a legacy NotificationsThemeSet from generated palettes and indicator colors.
 * Used by the provider-side handler to serve old Notification Center versions (<=2.13).
 */
export const buildLegacyNotificationsTheme = async (
    generatedPalettes: GeneratedPalettes,
    notificationIndicatorColors: NotificationIndicatorColorsParsed | null
): Promise<LegacyNotificationsThemeSet | null> => {
    try {
        // Use dist/theme sub-entry to avoid pulling in ui-library's heavy peer deps (react, styled-components, etc.)
        const { createTheme } = await import('@openfin/ui-library/dist/theme');
        const { light: lightPalette, dark: darkPalette } = mapGeneratedPalettesToLegacyPalettes(generatedPalettes);

        const lightTheme = createTheme(lightPalette as unknown as Record<string, string>);
        const darkTheme = createTheme(darkPalette as unknown as Record<string, string>);

        const lightResult: LegacyNotificationsThemeSet['light'] = { ...lightTheme };
        const darkResult: LegacyNotificationsThemeSet['dark'] = { ...darkTheme };

        if (notificationIndicatorColors?.light) {
            lightResult.notificationIndicatorColors = notificationIndicatorColors.light;
        }
        if (notificationIndicatorColors?.dark) {
            darkResult.notificationIndicatorColors = notificationIndicatorColors.dark;
        }

        return { light: lightResult, dark: darkResult };
    } catch (error) {
        log.error('buildLegacyNotificationsTheme', 'Failed to build legacy notifications theme', error);
        return null;
    }
};
