import { FC, useEffect, useMemo } from 'react';
import { useDispatch } from 'react-redux';

import Script from 'next/script';

import { ImportFonts } from '@openfin/ui-library';

import { useDocumentScheme } from '@common/components/StorageThemeProvider/useDocumentScheme';
import { varBasedTheme } from '@common/components/StorageThemeProvider/utils';
import ThemeProvider from '@common/components/ThemeProvider/ThemeProvider';
import { setCurrentScheme } from '@common/slices/target-theming';

import { useDeferShow } from '@common/hooks/useDeferShow';

interface TargetThemeProviderProps {
    fonts?: ImportFonts;
    children: React.ReactNode;
    themeLoader: (uuid: string) => void;
}

/**
 * Stragegic alternative to ThemeProvider, instead of using channels + explicit JS theme constants, it replaces
 * the theme with a constant value which references css-vars. This allows us to adopt a css-var based approach to theming
 * without needing to update every spot in our components where we reference a theme property.
 */
export const StorageThemeProvider: FC<TargetThemeProviderProps> = ({ children, fonts, themeLoader }) => {
    const setCanShow = useDeferShow();
    setCanShow(true);

    const dispatch = useDispatch();
    const scheme = useDocumentScheme();

    // TODO: Sync causes a double render when scheme changes; consider optimizing (e.g. single source of truth)
    // https://openfin.jira.com/browse/SAAS-4176
    useEffect(() => {
        dispatch(setCurrentScheme(scheme));
    }, [scheme, dispatch]);

    const theme = useMemo(() => varBasedTheme({} as any), []);

    return (
        <>
            <Script id="theme-applier" strategy="beforeInteractive">
                {`
                    (${themeLoader.toString()})(typeof fin !== 'undefined' && fin.me && fin.me.uuid ? fin.me.uuid : '')
                `}
            </Script>
            <ThemeProvider fonts={fonts} themes={{ light: theme, dark: theme }} scheme={scheme}>
                {children}
            </ThemeProvider>
        </>
    );
};
