import { FC } from 'react';
import React from 'react';
import { Provider } from 'react-redux';

import type { AppProps } from 'next/app';
import dynamic from 'next/dynamic';

import App, { SentryDynamic } from '@common/pages/_app';

import { setLocalBrowserUrl } from '@common/utils/browser-base-url';
import Route from '@common/utils/route';
import { getPathnameWithBasePath } from '@common/utils/router';
import { useSentryTagsBrowser } from '@common/utils/sentry';
import { currentOFIdentity } from '@common/utils/window';

import dockStore from '@common/components/Dock/store/store';

import { getEnterpriseBaseUrlFromHref } from '@enterprise/utils/base-url';
import { BrowserBaseUrlProvider } from '@enterprise/utils/base-url-context';

import BrowserThemeProvider from '@enterprise/components/App/ThemeProvider/BrowserThemeProvider';

import { BrowserContext } from '@common/hooks/context';
import { usePlatformLocalization } from '@common/hooks/usePlatformLocalization';
import browserStore from '@enterprise/store';

/**
 * Dynamic import that will only bundle dependencies required for showing a browser popup menu.
 */
const BrowserPopupMenuAppDynamic = dynamic(() => import('@enterprise/components/App/PopupMenu/PopupMenu'));

/**
 * Dynamic import that will only bundle Browser dependencies if required by the page.
 */
const BrowserWindowAppDynamic = dynamic(() => import('@enterprise/components/App/Window/Window'));

const BrowserApp: FC<AppProps> = (props) => {
    useSentryTagsBrowser();
    usePlatformLocalization(currentOFIdentity);

    const fullPath = getPathnameWithBasePath(props.router.pathname);

    if (fullPath.endsWith(Route.EnterpriseBrowser)) {
        return <BrowserWindowAppDynamic {...props} />;
    }
    if (fullPath.indexOf(Route.BrowserPopupMenu) !== -1) {
        return <BrowserPopupMenuAppDynamic {...props} />;
    }
    return (
        <BrowserThemeProvider>
            <App {...props} />
        </BrowserThemeProvider>
    );
};

const DockApp: FC<AppProps> = (props) => {
    useSentryTagsBrowser();
    usePlatformLocalization(currentOFIdentity);

    return <App {...props} />;
};

const BrowserAppCommon = (props: AppProps) => {
    if (typeof window !== 'undefined') setLocalBrowserUrl(getEnterpriseBaseUrlFromHref(window.location.href));
    const fullPath = getPathnameWithBasePath(props.router.pathname);
    if (fullPath.endsWith(Route.StorageProxy)) {
        return <App {...props} />;
    }
    if (fullPath.endsWith(Route.Dock)) {
        return (
            <Provider store={dockStore}>
                <DockApp {...props} />
            </Provider>
        );
    } else {
        return (
            <BrowserBaseUrlProvider>
                <Provider store={browserStore}>
                    <SentryDynamic />
                    <BrowserContext>
                        <BrowserApp {...props} />
                    </BrowserContext>
                </Provider>
            </BrowserBaseUrlProvider>
        );
    }
};

export default BrowserAppCommon;
