/**
 * Logger Utility for OpenFin Workspace Monorepo
 *
 * Provides structured, contextual logging with consistent formatting
 * across all workspaces and modules.
 */

export interface LogData {
    [key: string]: any;
}

export interface Logger {
    debug: (method: string, message: string, data?: LogData | (() => LogData)) => void;
    info: (method: string, message: string, data?: LogData | (() => LogData)) => void;
    warn: (method: string, message: string, data?: LogData | (() => LogData)) => void;
    error: (method: string, message: string, data?: LogData | (() => LogData)) => void;
}

/**
 * Configuration for the logger
 */
export interface LoggerConfig {
    /** Include timestamp in logs (default: true) */
    includeTimestamp?: boolean;
    /** Custom prefix for logs */
    customPrefix?: string;
    /**
     * Stringify log data before passing to console (default: true).
     * When true, objects are serialized as JSON strings for safer logging.
     * When false, raw objects are passed to console, allowing expandable/inspectable
     * objects in browser dev tools.
     *
     * @example
     * To disable safe stringify for local development, you can:
     * 1. Set this option per-logger: createLogger('MyContext', { stringifyData: false })
     * 2. Or call setGlobalStringifyEnabled(false) once at app startup
     */
    stringifyData?: boolean;
}

// =============================================================================
// Global Configuration
// =============================================================================

/**
 * Get the initial stringify setting from the build-time constant.
 * Defaults to true if LOG_STRINGIFY is not defined.
 */
const getInitialStringifyEnabled = (): boolean => {
    if (typeof LOG_STRINGIFY !== 'undefined') {
        return LOG_STRINGIFY === true;
    }
    return true;
};

/**
 * Global flag to enable/disable safe stringify for all loggers.
 * Initialized from the LOG_STRINGIFY build-time constant (set via OF__WORKSPACE_LOG_STRINGIFY env var).
 * Individual logger config takes precedence over this global setting.
 *
 * @see setGlobalStringifyEnabled
 */
let globalStringifyEnabled = getInitialStringifyEnabled();

/**
 * Enable or disable safe stringify globally for all loggers.
 * Useful for local development when you want expandable objects in browser dev tools.
 *
 * This overrides the build-time LOG_STRINGIFY setting at runtime.
 * Individual logger config (stringifyData option) takes precedence over this setting.
 *
 * @param enabled - Whether to stringify log data
 *
 * @example
 * ```typescript
 * // Override build-time setting at runtime:
 * import { setGlobalStringifyEnabled } from 'common/src/utils/logger';
 *
 * // Disable stringify to get expandable objects in console
 * setGlobalStringifyEnabled(false);
 * ```
 */
export const setGlobalStringifyEnabled = (enabled: boolean): void => {
    globalStringifyEnabled = enabled;
};

/**
 * Get the current global stringify setting.
 */
export const getGlobalStringifyEnabled = (): boolean => globalStringifyEnabled;

/**
 * Default logger configuration.
 * Note: stringifyData defaults to undefined here because its effective default
 * is controlled by globalStringifyEnabled when not explicitly set.
 */
const DEFAULT_CONFIG: Omit<Required<LoggerConfig>, 'stringifyData'> & { stringifyData: undefined } = {
    includeTimestamp: true,
    customPrefix: '',
    stringifyData: undefined
};

/**
 * Safely serialize data for logging, handling circular references and non-serializable types
 */
const safeStringify = (data: unknown): string => {
    try {
        return JSON.stringify(data, null, 2);
    } catch (error) {
        // Handle circular references and other non-serializable types
        try {
            const seen = new WeakSet();
            return JSON.stringify(
                data,
                (key, value) => {
                    // Handle circular references
                    if (typeof value === 'object' && value !== null) {
                        if (seen.has(value)) {
                            return '[Circular Reference]';
                        }
                        seen.add(value);
                    }

                    // Handle non-serializable types
                    if (typeof value === 'bigint') {
                        return `[BigInt: ${value.toString()}]`;
                    }
                    if (typeof value === 'function') {
                        return `[Function: ${value.name || 'anonymous'}]`;
                    }
                    if (typeof value === 'symbol') {
                        return `[Symbol: ${value.toString()}]`;
                    }
                    if (typeof value === 'undefined') {
                        return '[Undefined]';
                    }

                    return value;
                },
                2
            );
        } catch (innerError) {
            // Final fallback: return a safe string representation
            try {
                return `[Non-serializable: ${Object.prototype.toString.call(data)}]`;
            } catch {
                return '[Unable to serialize data]';
            }
        }
    }
};

/**
 * Format the log message with structured context
 */
const formatMessage = (context: string, method: string, message: string, config: Required<LoggerConfig>): string => {
    const timestamp = config.includeTimestamp ? new Date().toISOString() : '';
    const prefix = config.customPrefix ? `${config.customPrefix} ` : '';
    const timestampPart = timestamp ? `${timestamp} ` : '';

    return `${timestampPart}${prefix}[${context}][${method}] ${message}`;
};

/**
 * Process log data, handling lazy evaluation and optionally safe serialization.
 * When stringify is enabled, objects are serialized as JSON strings for safer logging.
 * When disabled, raw objects are returned for expandable console inspection.
 *
 * @param data - The log data or lazy function returning log data
 * @param shouldStringify - Whether to stringify the data (respects config and global setting)
 */
const processLogData = (
    data: LogData | (() => LogData) | undefined,
    shouldStringify: boolean
): string | LogData | undefined => {
    if (!data) return undefined;

    const actualData = typeof data === 'function' ? data() : data;

    if (!actualData) return undefined;

    return shouldStringify ? safeStringify(actualData) : actualData;
};

/**
 * Create a structured logger for a specific context
 *
 * @param context - The context identifier (workspace, module, or component name)
 * @param config - Optional configuration for the logger
 * @returns Enhanced logger instance
 *
 * @example
 * ```typescript
 * const logger = createLogger('browser.TabList');
 *
 * logger.info('addTab', 'Adding new tab', { pageId: '123' });
 * logger.error('addTab', 'Failed to add tab', { error: err.message });
 * ```
 */
export const createLogger = (context: string, config: LoggerConfig = {}): Logger => {
    const mergedConfig: Required<LoggerConfig> = {
        ...DEFAULT_CONFIG,
        ...config
    };

    // Determine if we should stringify: config takes precedence, then global setting
    const shouldStringify = (): boolean => {
        // If explicitly set in config, use that value
        if (config.stringifyData !== undefined) {
            return config.stringifyData;
        }
        // Otherwise fall back to global setting
        return globalStringifyEnabled;
    };

    const logWithLevel = (
        level: 'debug' | 'info' | 'warn' | 'error',
        method: string,
        message: string,
        data?: LogData | (() => LogData)
    ) => {
        // Wrap in try-catch to avoid potentially breaking business logic for the sake of logging
        try {
            const formattedMessage = formatMessage(context, method, message, mergedConfig);
            const processedData = processLogData(data, shouldStringify());

            const consoleMethod = console[level];

            if (processedData !== undefined) {
                consoleMethod(formattedMessage, processedData);
            } else {
                consoleMethod(formattedMessage);
            }
        } catch (error) {
            // Fallback to basic console logging if structured logging fails
            // This ensures logging errors never break application logic
            try {
                console.error('[Logger Error] Failed to log message:', error);
                console[level](`[${context}][${method}]`, message, data);
            } catch (fallbackError) {
                // This is the absolute last resort - silently fail to avoid breaking business logic
                // We intentionally swallow this error since there's nothing more we can do
                // and logging should never break the application
            }
        }
    };

    return {
        debug: (method, message, data) => logWithLevel('debug', method, message, data),
        info: (method, message, data) => logWithLevel('info', method, message, data),
        warn: (method, message, data) => logWithLevel('warn', method, message, data),
        error: (method, message, data) => logWithLevel('error', method, message, data)
    };
};

/**
 * Create a logger with performance monitoring capabilities
 * Useful for tracking execution times and performance metrics
 */
export const createPerformanceLogger = (context: string, config?: LoggerConfig) => {
    const logger = createLogger(context, config);
    const timers = new Map<string, number>();

    return {
        ...logger,

        /**
         * Start a performance timer
         */
        startTimer: (timerId: string, method: string, message: string, data?: LogData) => {
            timers.set(timerId, performance.now());
            logger.debug(method, message, data);
        },

        /**
         * Clear a specific timer without logging
         */
        clearTimer: (timerId: string) => {
            timers.delete(timerId);
        },

        /**
         * End a performance timer and log the duration
         */
        endTimer: (timerId: string, method: string, message: string, data?: LogData) => {
            const startTime = timers.get(timerId);
            if (startTime !== undefined) {
                const duration = performance.now() - startTime;
                const enhancedData = { ...data, duration: `${duration.toFixed(2)}ms` };
                logger.info(method, message, enhancedData);
                timers.delete(timerId);
            } else {
                logger.warn(method, `Timer ${timerId} not found`, data);
            }
        }
    };
};

export type EnhancedLogger = ReturnType<typeof createPerformanceLogger>;

/**
 * Middleware function for wrapping async operations with logging
 */
export const withLogging = <T extends any[], R>(
    logger: Logger,
    method: string,
    operation: (...args: T) => Promise<R> | R
) => {
    return async (...args: T): Promise<R> => {
        const operationId = `${method}-${Date.now()}`;

        try {
            logger.debug(method, `Executing ${method}`, { operationId });
            const result = await operation(...args);
            logger.debug(method, `Successfully executed ${method}`, { operationId });
            return result;
        } catch (error) {
            logger.error(method, `Failed to execute ${method}`, {
                operationId,
                error: error instanceof Error ? error.message : String(error)
            });
            throw error;
        }
    };
};

