/**
 * Checks if we're running in a browser environment (not during SSG/build).
 */
const isBrowserRuntime = (): boolean => {
    return typeof window !== 'undefined' && typeof document !== 'undefined';
};

/**
 * Whether debug logging is enabled.
 * - During build/SSG: Always disabled to reduce build noise
 * - At browser runtime: Controlled by LOG_DEBUG build-time constant
 */
const getIsDebugEnabled = (): boolean => {
    // Suppress debug logs during SSG/build (runs in Node.js without window)
    if (!isBrowserRuntime()) {
        return false;
    }
    // At browser runtime, check the build-time constant
    if (typeof LOG_DEBUG !== 'undefined') {
        return LOG_DEBUG === true;
    }
    return false;
};

/**
 * Logs the specified kind of log while converting JS objects to json strings safely.
 * Respects the global stringify setting (see setGlobalStringifyEnabled).
 * @param type the log function to execute, e.g. 'debug', 'info'
 * @param args values to log
 */
const strLog = (type: 'info' | 'debug' | 'error' | 'warn' | 'trace', ...args: unknown[]) => {
    const logFunc = console[type];
    // wrap in try-catch to avoid potentially breaking business logic for the sake of logging
    try {
        // Respect global stringify setting
        if (globalStringifyEnabled) {
            const stringifiedArgs = args.map((arg) =>
                typeof arg === 'object' && arg !== null ? safeStringify(arg) : arg
            );
            logFunc(...stringifiedArgs);
        } else {
            logFunc(...args);
        }
    } catch (error) {
        console.error('Error printing stringified log, logging directly', error);
        logFunc(...args);
    }
};

/**
 * Legacy logger instance for backwards compatibility.
 * Use `createLogger` for new code to get structured, contextual logging.
 *
 * @deprecated Use createLogger() instead for new code
 */
export const log = {
    /**
     * Calls console.debug with provided parameters and stringifies JS objects prior to logging.
     * Only logs when LOG_DEBUG is enabled.
     */
    debug: (...args: unknown[]) => {
        if (getIsDebugEnabled()) {
            strLog('debug', ...args);
        }
    },
    /**
     * Calls console.info with provided parameters and stringifies JS objects prior to logging
     */
    info: (...args: unknown[]) => strLog('info', ...args),
    /**
     * Calls console.warn with provided parameters and stringifies JS objects prior to logging
     */
    warn: (...args: unknown[]) => strLog('warn', ...args),
    /**
     * Calls console.error with provided parameters and stringifies JS objects prior to logging
     */
    error: (...args: unknown[]) => strLog('error', ...args),
    /**
     * Calls console.trace with provided parameters and stringifies JS objects prior to logging
     */
    trace: (...args: unknown[]) => strLog('trace', ...args)
};
