import type OpenFin from '@openfin/core';

import { connectToContextMenuChannel } from '@common/utils/enterprise-channels';

import { t } from '@common/api/i18next';

import { AnchorBehavior } from '@client-platform/api/context-menu';

import {
    PageTabContextMenuItemTemplate,
    ViewTabContextMenuTemplate,
    ViewTabMenuOptionType
} from '@client-platform/shapes';

import { isFin } from './env';
import { ContextMenuChannelMessage, PopupWindowMenuType } from './popup-window';
import { randomUUID } from './uuid';
import { currentOFIdentity } from './window';

export enum MenuItemType {
    Label = 'normal',
    Separator = 'separator',
    Submenu = 'submenu',
    Checkbox = 'checkbox'
}

export type ShowContextMenuResponse = OpenFin.MenuResult & { data: any; requestId?: string };

let contextMenuInvocationLock = { locked: false, x: -1, y: -1 };

const isEnterpriseContextMenuLocked = (x: number, y: number) => {
    const { x: prevX, y: prevY, locked } = contextMenuInvocationLock;
    return locked && x === prevX && y === prevY;
};

export function showContextMenu(opts: OpenFin.ShowPopupMenuOptions, win?: OpenFin.Window) {
    if (!isFin) {
        throw new Error(
            'showContextMenu can only be used in an OpenFin env. Avoid calling this method during pre-rendering.'
        );
    }

    if (!win && !fin.me.isWindow) {
        throw new Error('showContextMenu can only be used in an OpenFin window.');
    }

    const currentWindow = win || fin.Window.getCurrentSync();

    return currentWindow.showPopupMenu(opts) as Promise<ShowContextMenuResponse>;
}

export const showEnterpriseContextMenu = async (
    opts: OpenFin.ShowPopupMenuOptions,
    type: PopupWindowMenuType,
    anchorBehavior: AnchorBehavior,
    win?: OpenFin.Window
): Promise<ShowContextMenuResponse> => {
    if (!isFin) {
        throw new Error(
            'showEnterpriseContextMenu can only be used in a HERE env. Avoid calling this method during pre-rendering.'
        );
    }

    if (!win && !fin.me.isWindow) {
        throw new Error('showEnterpriseContextMenu can only be used in a HERE window.');
    }

    const { x, y, template } = opts;

    // Context menu handler sometimes gets fires twice from a DOM interaction. This lock ensures it only attempts invoking the context menu window once.
    if (isEnterpriseContextMenuLocked(x, y)) {
        return new Promise<ShowContextMenuResponse>((resolve, _) =>
            resolve({ data: undefined } as ShowContextMenuResponse)
        );
    }
    contextMenuInvocationLock = { locked: true, x, y };

    const contextMenuChannel = await connectToContextMenuChannel();

    // Listen for responses over a topic with a specific requestId to resolve invocations in a targeted manner.
    const requestId = randomUUID();
    const response = new Promise((resolve, _) => {
        contextMenuChannel.register(`response-${requestId}`, (responseData: ShowContextMenuResponse) => {
            contextMenuInvocationLock.locked = false;
            contextMenuChannel.remove(`response-${requestId}`);
            resolve(responseData as ShowContextMenuResponse);
        });
    });

    await contextMenuChannel.dispatch('open', {
        parentIdentity: win.identity,
        responseIdentity: currentOFIdentity,
        requestId,
        type,
        anchorBehavior,
        x,
        y,
        payload: { template }
    } as ContextMenuChannelMessage);

    return response as Promise<ShowContextMenuResponse>;
};

export const Separator: OpenFin.MenuItemTemplate = {
    type: MenuItemType.Separator,
    data: undefined
};

export const EmptyContextMenuItem: OpenFin.MenuItemTemplate = {
    type: 'normal',
    enabled: false,
    label: 'No options available'
};

export const DefaultSaveMenuBounds = {
    width: 247,
    height: 120
};

export const getBoundsBasedOnAnchorBehavior = (bounds: OpenFin.Bounds, anchorBehavior: AnchorBehavior) => {
    switch (anchorBehavior) {
        case AnchorBehavior.BottomRight:
            return { ...bounds, left: bounds.left - bounds.width };
        case AnchorBehavior.TopLeft:
            return { ...bounds, bottom: bounds.top - bounds.height };
        case AnchorBehavior.TopRight:
            return { ...bounds, left: bounds.left - bounds.width, bottom: bounds.top - bounds.height };
        default:
            return bounds;
    }
};

export const getPrintOption = async (): Promise<ViewTabContextMenuTemplate | PageTabContextMenuItemTemplate> => {
    return {
        type: MenuItemType.Submenu,
        label: t('contextMenu.print'),
        submenu: [
            {
                type: MenuItemType.Label,
                label: t('contextMenu.submenu.print'),
                data: { type: ViewTabMenuOptionType.Print }
            },
            {
                type: MenuItemType.Label,
                label: t('contextMenu.submenu.printAll'),
                data: { type: ViewTabMenuOptionType.PrintAll }
            },
            // TODO: remove cast once @openfin/core updates their types
            Separator as ViewTabContextMenuTemplate,
            {
                type: MenuItemType.Label,
                label: t('contextMenu.printScreen'),
                data: { type: ViewTabMenuOptionType.PrintScreen }
            }
        ]
    };
};
