import { createSlice, PayloadAction } from '@reduxjs/toolkit';

export interface PagesModalRootState {
    modal: {
        openModalWindows: Record<string, boolean>;
    };
}

export const modalSlice = createSlice({
    name: 'modal',
    initialState: {
        openModalWindows: {} as Record<string, boolean>
    },
    reducers: {
        openModal: (state, action: PayloadAction<string>) => {
            state.openModalWindows[action.payload] = true;
        },
        closeModal: (state, action: PayloadAction<string>) => {
            state.openModalWindows[action.payload] = false;
        }
    }
});

export const { openModal, closeModal } = modalSlice.actions;

export const selectIsModalOpen = (state: PagesModalRootState) =>
    state.modal?.openModalWindows ? Object.values(state.modal.openModalWindows).some(Boolean) : false;

export const selectHasModalWindow = (state: PagesModalRootState, name: string) =>
    state.modal?.openModalWindows?.[name] ?? false;

export default modalSlice.reducer;
