import type OpenFin from '@openfin/core';

import { showContextMenu, showEnterpriseContextMenu } from '@common/utils/context-menu';
import { getEnterpriseContextMenuTemplate } from '@common/utils/enterprise-menu';
import { isEnterpriseBrowser } from '@common/utils/enterpriseBrowser';
import { getGlobalContextMenuTemplate } from '@common/utils/global-context-menu';
import { getPageTabMenuTemplate } from '@common/utils/page-tab-context-menu';
import { PopupWindowMenuType } from '@common/utils/popup-window';
import { getSaveButtonMenuTemplate } from '@common/utils/save-button-context-menu';

import {
    GlobalContextMenuItemTemplate,
    GlobalContextMenuOptionType,
    InternalOpenGlobalContextMenuRequest,
    InternalOpenPageTabContextMenuRequest,
    OpenGlobalContextMenuPayload,
    OpenPageTabContextMenuPayload,
    OpenSaveButtonContextMenuPayload,
    OpenSaveButtonContextMenuRequest,
    OpenViewTabContextMenuPayload,
    OpenViewTabContextMenuRequest,
    PageTabContextMenuItemData,
    WorkspacePlatformProvider
} from '@client-platform/shapes';

import { getPlatformLabel } from '../../init/platform-label';
import {
    contextMenuPerformanceMarkAPIReturn,
    contextMenuPerformanceMarkStart,
    setupContextMenuPerformanceMark
} from '../performance';

import globalContextMenuResponseHandler from './browser-logo-handler';
import { pageTabContextMenuItemHandler } from './browser-pagetab-handler';
import { saveButtonContextMenuItemHandler } from './browser-savebutton-handler';
import viewTabContextMenuResponseHandler from './browser-viewtab-handler';

/**
 * Enum representing the possible anchor behaviors for positioning context menus.
 * These are relative to an element/cursor position (as opposed to a corner of the context menu window).
 *
 * e.g. AnchorBehavior.BottomRight implies a context menu will expand aligned with the bottom and right edge of an element.
 *
 * @enum {number}
 */
export enum AnchorBehavior {
    TopLeft,
    TopRight,
    BottomLeft,
    BottomRight,
    Center
}

type ContextMenuPayload =
    | OpenGlobalContextMenuPayload
    | OpenViewTabContextMenuPayload
    | OpenPageTabContextMenuPayload
    | OpenSaveButtonContextMenuPayload;

/* All overrideable context menus are ultimately opened by this function */
export const openCommonContextMenu = async (
    payload: ContextMenuPayload,
    _callerIdentity: OpenFin.Identity,
    type?: PopupWindowMenuType,
    anchorBehavior?: AnchorBehavior
) => {
    const { x, y, identity, template, callback } = payload;
    const isEnterprise = await isEnterpriseBrowser(identity);
    const { data } = isEnterprise
        ? await showEnterpriseContextMenu(
              {
                  x,
                  y,
                  template
              },
              type,
              anchorBehavior,
              fin.Window.wrapSync(identity)
          )
        : await showContextMenu(
              {
                  x,
                  y,
                  template
              },
              fin.Window.wrapSync(identity)
          );
    callback(data as any, payload as any);
};

// WARNING: don't convert this to an arrow function - we bind a value for `this` elsewhere
export async function openGlobalContextMenuInternal(
    this: WorkspacePlatformProvider,
    payload: InternalOpenGlobalContextMenuRequest & { identity: OpenFin.Identity },
    callerIdentity: OpenFin.Identity
) {
    const performanceMarkTitle = contextMenuPerformanceMarkStart();
    const isEnterprise = await isEnterpriseBrowser(payload.identity);
    if (isEnterprise) {
        // For EB it is a container window but non-EB is OS level context menu
        setupContextMenuPerformanceMark(performanceMarkTitle);
    }
    const template = isEnterprise
        ? ((await getEnterpriseContextMenuTemplate({
              identity: payload.identity,
              selectedViews: payload.selectedViews
          })) as any)
        : await getGlobalContextMenuTemplate(payload.identity, payload.selectedViews);

    // get platform label
    const platformLabel = await getPlatformLabel();

    if (!isEnterprise) {
        // update window quit platform label
        template.find(
            (o: GlobalContextMenuItemTemplate) => o.data?.type === GlobalContextMenuOptionType.Quit
        ).label = `Quit ${platformLabel}`;
    }

    // Enterprise custom context menu is right-aligned with the global context menu button
    const { rect, ...payloadWithoutRect } = payload;
    const { x, y } = isEnterprise ? { x: rect.left + rect.width, y: rect.bottom } : payload;

    const modifiedPayload = {
        ...payloadWithoutRect,
        x,
        y,
        template,
        callback: globalContextMenuResponseHandler
    };
    // For non-EB this is right before we call the OS API so should be a great mark,
    // for EB we still have to show our own menu so could take some time but we have a show event to track
    contextMenuPerformanceMarkAPIReturn(performanceMarkTitle);
    // call via `this` to pick up any potential end-user overrides
    await this.openGlobalContextMenu(modifiedPayload, callerIdentity);
}

export async function openViewTabContextMenuInternal(
    this: WorkspacePlatformProvider,
    payload: OpenViewTabContextMenuRequest & { identity: OpenFin.Identity },
    callerIdentity: OpenFin.Identity
) {
    const modifiedPayload = {
        ...payload,
        callback: viewTabContextMenuResponseHandler
    };
    // call via `this` to pick up any potential end-user overrides
    await this.openViewTabContextMenu(modifiedPayload, callerIdentity);
}

export async function openPageTabContextMenuInternal(
    this: WorkspacePlatformProvider,
    payload: InternalOpenPageTabContextMenuRequest & { identity: OpenFin.Identity },
    callerIdentity: OpenFin.Identity
) {
    const performanceMarkTitle = contextMenuPerformanceMarkStart();
    const isEnterprise = await isEnterpriseBrowser(payload.identity);
    if (isEnterprise) {
        // For EB it is a container window but non-EB is OS level context menu
        setupContextMenuPerformanceMark(performanceMarkTitle);
    }
    const template = await getPageTabMenuTemplate(payload.pageId, payload.identity, isEnterprise);
    const modifiedPayload = {
        ...payload,
        template,
        callback: (d: PageTabContextMenuItemData, p: OpenPageTabContextMenuPayload) => {
            pageTabContextMenuItemHandler(d, p, payload.rect);
        }
    };
    // For non-EB this is right before we call the OS API so should be a great mark,
    // for EB we still have to show our own menu so could take some time but we have a show event to track
    contextMenuPerformanceMarkAPIReturn(performanceMarkTitle);
    // call via `this` to pick up any potential end-user overrides
    await this.openPageTabContextMenu(modifiedPayload, callerIdentity);
}

export async function openSaveButtonContextMenuInternal(
    this: WorkspacePlatformProvider,
    payload: OpenSaveButtonContextMenuRequest & { identity: OpenFin.Identity },
    callerIdentity: OpenFin.Identity
) {
    const template = await getSaveButtonMenuTemplate(payload.pageId);
    const modifiedPayload = {
        ...payload,
        template,
        callback: saveButtonContextMenuItemHandler
    };
    // call via `this` to pick up any potential end-user overrides
    await this.openSaveButtonContextMenu(modifiedPayload, callerIdentity);
}
