import type OpenFin from '@openfin/core';

import { CustomContextMenuTemplate } from '@openfin/ui-library';

import { getPrintOption, MenuItemType, Separator } from '@common/utils/context-menu';
import { countViews } from '@common/utils/layout';
import { getOFWindow } from '@common/utils/window';

import { t } from '@common/api/i18next';
import { AttachedPage } from '@common/api/pages/enterprise-shapes';

import { getAllAttachedPages } from '@client-platform/api/pages';

import { getCurrentSync } from '@client-platform/index';
import {
    PageTabContextMenuItemData,
    PageTabContextMenuItemTemplate,
    PageTabContextMenuOptionType
} from '@client-platform/shapes';

import { ENTERPRISE_COLOR_CHANNELS } from './color-linking';

export const getPageTabMenuTemplate = async (
    pageId: string,
    winIdentity: OpenFin.Identity,
    isEnterprise: boolean
): Promise<PageTabContextMenuItemTemplate[]> => {
    const savedPage = await getCurrentSync().Storage.getPage(pageId);
    const attachedPages = await getAllAttachedPages();
    const page = attachedPages.find((p) => p.pageId === pageId) as AttachedPage | undefined;
    if (!page) return [];
    const isUngrouped = !page.pinned;
    const { workspacePlatform } = await getOFWindow(winIdentity).getOptions();
    const canUnpin = page.pinned === 'user' && !isEnterprise;
    const isPlatformLocked = page.pinned === 'platform';
    const isSuperTab = countViews(page.layout.content) > 1;
    const closeEnabled = !(
        workspacePlatform.isLocked ||
        workspacePlatform.preventPageClose ||
        page.closeButton?.disabled ||
        page.closeButton?.hidden ||
        page.pinned === 'platform'
    );

    const enterpriseTabContextMenuItems: CustomContextMenuTemplate[] = [
        {
            type: MenuItemType.Label,
            label: t('enterpriseContextMenu.newTab'),
            data: {
                type: PageTabContextMenuOptionType.NewPage
            }
        },
        Separator as CustomContextMenuTemplate,
        getAddPageToChannelOption(page),
        getManageDesktopSignalsOption(),
        Separator as CustomContextMenuTemplate,
        {
            type: MenuItemType.Label,
            label: t('reload'),
            data: {
                type: PageTabContextMenuOptionType.Refresh
            }
        },
        {
            type: MenuItemType.Label,
            label: t('enterpriseContextMenu.duplicate'),
            data: {
                type: PageTabContextMenuOptionType.Duplicate
            },
            enabled: !workspacePlatform.isLocked
        },
        (await getPrintOption()) as CustomContextMenuTemplate,
        Separator as CustomContextMenuTemplate,
        {
            type: MenuItemType.Label,
            label: t(isSuperTab ? 'enterpriseSaveModal.closeSupertab' : 'enterpriseSaveModal.closeTab'),
            data: {
                type: PageTabContextMenuOptionType.Close
            },
            enabled: closeEnabled
        }
    ];

    const enterpriseSupertabContextMenuItems: CustomContextMenuTemplate<PageTabContextMenuItemData>[] = [
        {
            type: MenuItemType.Label,
            label: t('enterpriseContextMenu.newTab'),
            data: {
                type: PageTabContextMenuOptionType.NewPage
            }
        },
        Separator as CustomContextMenuTemplate<PageTabContextMenuItemData>,
        getAddPageToChannelOption(page),
        getManageDesktopSignalsOption(),
        Separator as CustomContextMenuTemplate<PageTabContextMenuItemData>,
        {
            type: MenuItemType.Label,
            label: t('enterpriseSaveModal.renameSupertab'),
            data: {
                type: PageTabContextMenuOptionType.Rename
            },
            enabled: !workspacePlatform.isLocked && !isPlatformLocked && !!savedPage && isSuperTab
        },
        {
            type: MenuItemType.Label,
            label: t('enterpriseContextMenu.duplicate'),
            data: {
                type: PageTabContextMenuOptionType.Duplicate
            },
            enabled: !workspacePlatform.isLocked
        },
        Separator as CustomContextMenuTemplate<PageTabContextMenuItemData>,
        {
            type: MenuItemType.Label,
            label: t('enterpriseContextMenu.saveSupertab'),
            data: {
                type: PageTabContextMenuOptionType.Save
            },
            enabled: isSuperTab && !!savedPage && !isPlatformLocked
        },
        {
            type: MenuItemType.Label,
            label: t('enterpriseContextMenu.saveSupertabAs'),
            data: {
                type: PageTabContextMenuOptionType.SaveAs
            },
            enabled: isSuperTab
        },
        Separator as CustomContextMenuTemplate<PageTabContextMenuItemData>,
        {
            type: MenuItemType.Label,
            label: t('enterpriseContextMenu.deleteSupertab'),
            data: {
                type: PageTabContextMenuOptionType.DeletePage
            },
            enabled: !!savedPage
        },
        Separator as CustomContextMenuTemplate<PageTabContextMenuItemData>,
        {
            type: MenuItemType.Label,
            label: t(isSuperTab ? 'enterpriseSaveModal.closeSupertab' : 'enterpriseSaveModal.closeTab'),
            data: {
                type: PageTabContextMenuOptionType.Close
            },
            enabled: closeEnabled
        }
    ];

    const pageTabContextMenuItems = [
        {
            type: MenuItemType.Label,
            label: t('contextMenu.savePage'),
            data: {
                type: PageTabContextMenuOptionType.Save
            },
            enabled: !!savedPage && !isPlatformLocked
        },
        {
            type: MenuItemType.Label,
            label: t('saveMenu.savePageAs'),
            data: {
                type: PageTabContextMenuOptionType.SaveAs
            },
            enabled: true
        },
        {
            type: MenuItemType.Label,
            label: 'Save Workspace As',
            data: {
                type: PageTabContextMenuOptionType.SaveWorkspaceAs
            }
        },
        {
            type: MenuItemType.Label,
            label: 'Refresh',
            data: {
                type: PageTabContextMenuOptionType.Refresh
            }
        },
        // TODO: remove cast once @openfin/core updates their types
        Separator as PageTabContextMenuItemTemplate,
        // insert rename here
        {
            type: MenuItemType.Label,
            label: t('saveModal.renamePage'),
            data: {
                type: PageTabContextMenuOptionType.Rename
            },
            enabled: !!savedPage && !isPlatformLocked
        },
        {
            type: MenuItemType.Label,
            label: t('contextMenu.duplicatePage'),
            data: {
                type: PageTabContextMenuOptionType.Duplicate
            },
            enabled: !workspacePlatform.isLocked
        },
        ...(isUngrouped
            ? [
                  {
                      type: MenuItemType.Label,
                      label: t('contextMenu.pinPage'),
                      data: {
                          type: PageTabContextMenuOptionType.Pin
                      },
                      enabled: !workspacePlatform.isLocked
                  } as PageTabContextMenuItemTemplate
              ]
            : []),
        ...(canUnpin
            ? [
                  {
                      type: MenuItemType.Label,
                      label: t('contextMenu.unpinPage'),
                      data: {
                          type: PageTabContextMenuOptionType.Unpin
                      },
                      enabled: !workspacePlatform.isLocked
                  } as PageTabContextMenuItemTemplate
              ]
            : []),
        // TODO: remove cast once @openfin/core updates their types
        Separator as PageTabContextMenuItemTemplate,
        {
            type: MenuItemType.Label,
            label: t('saveModal.closePage'),
            data: {
                type: PageTabContextMenuOptionType.Close
            },
            enabled: closeEnabled
        }
    ];

    if (isEnterprise) {
        return (
            isSuperTab ? enterpriseSupertabContextMenuItems : enterpriseTabContextMenuItems
        ) as PageTabContextMenuItemTemplate[];
    }
    return pageTabContextMenuItems;
};

function getManageDesktopSignalsOption(): CustomContextMenuTemplate<PageTabContextMenuItemData> {
    return {
        type: MenuItemType.Label,
        label: t('contextMenu.manageDesktopSignals'),
        data: {
            type: PageTabContextMenuOptionType.ManageDesktopSignals
        }
    };
}

function getAddPageToChannelOption(page: AttachedPage): CustomContextMenuTemplate<PageTabContextMenuItemData> {
    const CHANNELS = Array.from(ENTERPRISE_COLOR_CHANNELS.entries());
    const currentContextGroup = page.contextGroup;
    return {
        type: 'widget',
        config: {
            type: 'add-to-channel',
            channels: [
                ...CHANNELS.map(([channelId, metadata]) => ({
                    label: metadata.name,
                    data: { type: PageTabContextMenuOptionType.AddToChannel, option: channelId },
                    color: metadata.color,
                    checked: currentContextGroup === channelId
                })),
                {
                    label: 'unlink',
                    data: { type: PageTabContextMenuOptionType.AddToChannel, option: 'unlink' },
                    isNone: true
                }
            ]
        },
        label: 'Link to Channel'
    };
}
