import { configureStore } from '@reduxjs/toolkit';

import environmentReducer from '@common/slices/environment';
import findInPageReducer from '@common/slices/find-in-page';
import targetThemingReducer from '@common/slices/target-theming';
import modalReducer from '@common/slices/modal';

import attachedPagesReducer from '@enterprise/slices/pages/attached';

import menuReducer from '@enterprise/slices/menu';
import pagesLoadingReducer from '@enterprise/slices/pages-loading';
import tabFocusReducer from '@enterprise/slices/tab-focus';
import viewTabReducer from '@enterprise/slices/view-tab-icons';

/**
 * Redux store for a Browser Window.
 */
const store = configureStore({
    reducer: {
        environment: environmentReducer,
        modal: modalReducer,
        attachedPages: attachedPagesReducer,
        tabFocus: tabFocusReducer,
        menu: menuReducer,
        targetTheming: targetThemingReducer,
        viewTabIcons: viewTabReducer,
        pagesLoading: pagesLoadingReducer,
        findInPage: findInPageReducer
    }
});
export default store;

export type BrowserRootState = ReturnType<typeof store.getState>;
