import { createSlice, PayloadAction } from '@reduxjs/toolkit';

import { enableMapSet } from 'immer';

import { isLandingPage } from '@common/utils/enterpriseBrowser';
enableMapSet();

type PageTabState = {
    currentView?: { isLoading: boolean; viewName: string; isNewTab: boolean };
    canShow: boolean;
};
/**
 * @description For each layoutContainerKey, we store a set of view names that are actively loading.
 * If the set is empty, the page is not loading.
 * If the set is non-empty, the page is loading.
 */
interface PagesLoadingState {
    [layoutContainerKey: string]: PageTabState;
}

interface PagesLoadingRootState {
    pagesLoading: PagesLoadingState;
}

// Initial state
const initialState: PagesLoadingState = {};

const pagesLoadingSlice = createSlice({
    name: 'pagesLoading',
    initialState,
    reducers: {
        removePageState: (state, action: PayloadAction<{ layoutContainerKey: string }>) => {
            const { layoutContainerKey } = action.payload;
            delete state[layoutContainerKey];
        },
        setPageSingleViewState: (
            state,
            action: PayloadAction<{ layoutContainerKey: string; viewName: string; url: string }>
        ) => {
            const { viewName, url, layoutContainerKey } = action.payload;
            const isLanding = isLandingPage(url);
            state[layoutContainerKey] = {
                ...state[layoutContainerKey],
                canShow: true,
                currentView: {
                    isLoading: false,
                    viewName,
                    isNewTab: isLanding
                }
            };
        },
        /**
         * @description Add a viewName to the set of loading views for this pageId
         * @param pageId - The id of the page to add the viewName to.
         * @param viewName - The name of the view to add to the set.
         */
        onViewUrlChanged: (
            state,
            action: PayloadAction<{ layoutContainerKey: string; viewName: string; url: string }>
        ) => {
            const { layoutContainerKey, viewName, url } = action.payload;
            const isLanding = isLandingPage(url);

            state[layoutContainerKey] = {
                ...state[layoutContainerKey],
                currentView: { isLoading: true, viewName, isNewTab: isLanding }
            };
        },
        /**
         * @description Remove a viewName from the set of loading views for this pageId
         * @param pageId - The id of the page to remove the viewName from.
         * @param viewName - The name of the view to remove from the set.
         */
        onViewStoppedLoading: (state, action: PayloadAction<{ layoutContainerKey: string; viewName: string }>) => {
            const { layoutContainerKey, viewName } = action.payload;
            const page = state[layoutContainerKey];
            if (!page) {
                return;
            }

            if (page.currentView) {
                if (page.currentView.viewName === viewName) {
                    page.currentView.isLoading = false;
                }
            }
        }
    }
});

export const { onViewUrlChanged, onViewStoppedLoading, removePageState, setPageSingleViewState } =
    pagesLoadingSlice.actions;
export default pagesLoadingSlice.reducer;

/**
 * @description Selector to check if a page is loading.
 * @param layoutContainerKey - The layout name of the page.
 * @returns True if the page is loading, false otherwise.
 */
export const selectPageTabState =
    (layoutContainerKey: string) =>
    (state: PagesLoadingRootState): PageTabState | undefined => {
        return state.pagesLoading[layoutContainerKey];
    };
