import type OpenFin from '@openfin/core';

import type { ContentMenuEntry } from '@openfin/ui-library';

import { finEntityType, finName, finUUID } from '@common/utils/env';
import type { AnalyticsEventInternal } from '@common/utils/usage-register';

import {
    getWorkspacePlatformChannelClient,
    internalGetWorkspacePlatformChannelClient,
    PlatFormSupportedFeatures,
    WorkspacePlatformChannelAction
} from '@common/api/protocol/workspace-platform';
import { NotificationsCustomManifestOptions } from '@common/api/shapes/notifications';

import {
    AboutPageConfig,
    ApplyWorkspaceOptions,
    BrowserCreateViewRequest,
    BrowserSnapshot,
    BrowserViewState,
    Collection,
    CustomActionCallerType,
    CustomActionPayload,
    DockCompanionButton,
    DockEntry,
    GetCurrentWorkspaceOptions,
    LaunchBookmarkPayload,
    LaunchDockEntryPayload,
    Locale,
    RestoreLastSavedWorkspaceResult,
    ShowQuitPlatformDialogRequest,
    ShowUpdateVersionModalRequest,
    Workspace,
    WorkspacePlatformModule
} from '../shapes';
import { InvokeCustomActionRequest, LaunchAppRequest } from '..';

import { getBrowserApi } from './browser';
import { showAboutPagePopup } from './modal';
import { getStorageApi } from './storage';
import { getThemingApi } from './theming';

/**
 * Synchronously returns a Platform object that represents an existing platform.
 *
 * ```ts
 * import * as WorkspacePlatform from '@openfin/workspace-platform';
 *
 * // declare platform identity
 * const myPlatformIdentity: OpenFin.ApplicationIdentity = {
 *      uuid: 'testPlatform',
 *      name: 'Test Platform'
 * };
 *
 * // get the platform representing myPlatformIdentity
 * const platform = WorkspacePlatform.wrapSync(myPlatformIdentity);
 *
 * // do something with platform. e.g. create a window
 * platform.createWindow({
 *      layout: {
 *          content: [
 *              {
 *                  type: 'component',
 *                  componentName: 'Example View',
 *                  componentState: {
 *                      name: 'example_view_1'
 *                      url: 'https://developer.openfin.co/docs/javascript/stable/index.html'
 *                  }
 *              }
 *          ]
 *      }
 * });
 * ```
 */
export const wrapSync = (identity: OpenFin.ApplicationIdentity): WorkspacePlatformModule => {
    const platform = fin.Platform.wrapSync(identity);
    let supportedFeatures: PlatFormSupportedFeatures;

    const platformModule = Object.assign(platform, {
        applySnapshot: async (
            snapshot: BrowserSnapshot | string,
            options?: OpenFin.ApplySnapshotOptions
        ): Promise<OpenFin.Platform> => {
            if (typeof snapshot !== 'string' && !snapshot?.windows) {
                throw new Error('Not a valid browser snapshot');
            }
            return fin.Platform.wrapSync(identity).applySnapshot(snapshot, options);
        },
        getSnapshot: () =>
            fin.Platform.wrapSync(identity)
                .getSnapshot()
                .then((snapshot) => snapshot as BrowserSnapshot),

        getViewSnapshot: (viewIdentity: OpenFin.Identity): Promise<BrowserViewState> =>
            fin.Platform.wrapSync(identity).getViewSnapshot(viewIdentity),

        createView: (
            viewOptions: Partial<OpenFin.ViewOptions> | BrowserCreateViewRequest,
            target?: OpenFin.CreateViewTarget,
            targetView?: OpenFin.Identity
        ) => fin.Platform.wrapSync(identity).createView(viewOptions, target, targetView),

        launchApp: async (req: LaunchAppRequest): Promise<void> => {
            console.warn(
                'launchApp method is deprecated. It is recommended to use createView - https://developers.openfin.co/of-docs/docs/platform-getting-started#add-a-view-to-an-existing-window or  ' +
                    'createWindow - https://developers.openfin.co/of-docs/docs/platform-getting-started#create-a-platform-window instead.'
            );
            if (!req.target) {
                req.target = { uuid: finUUID, name: finName, entityType: finEntityType || 'unknown' };
            }
            const client = await getWorkspacePlatformChannelClient(identity);
            return client.dispatch(WorkspacePlatformChannelAction.LaunchApp, req);
        },
        _invokeCustomAction: async (actionId: string, payload: CustomActionPayload) => {
            const client = await getWorkspacePlatformChannelClient(identity);
            const req: InvokeCustomActionRequest = {
                actionId,
                payload: {
                    ...payload,
                    callerType: (payload.callerType as any) || CustomActionCallerType.API
                }
            };
            return client.dispatch(WorkspacePlatformChannelAction.InvokeCustomActionInternal, req);
        },
        _requestQuitPlatformDialog: async (req: ShowQuitPlatformDialogRequest) => {
            const client = await getWorkspacePlatformChannelClient(identity);
            return client.dispatch(WorkspacePlatformChannelAction.RequestQuitPlatformDialogInternal, req);
        },
        _showUpdateVersionModal: async (req: ShowUpdateVersionModalRequest) => {
            const client = await getWorkspacePlatformChannelClient(identity);
            return client.dispatch(WorkspacePlatformChannelAction.ShowUpdateVersionModalInternal, req);
        },
        _showApplyAndPublishModal: async () => {
            const client = await getWorkspacePlatformChannelClient(identity);
            return client.dispatch(WorkspacePlatformChannelAction.ShowApplyAndPublishModalInternal, undefined);
        },
        getCurrentWorkspace: async (options?: GetCurrentWorkspaceOptions): Promise<Workspace> => {
            const channel = await getWorkspacePlatformChannelClient(identity);
            return channel.dispatch(WorkspacePlatformChannelAction.GetCurrentWorkspace, options);
        },
        applyWorkspace: async (workspace: Workspace, options?: ApplyWorkspaceOptions): Promise<boolean | undefined> => {
            const channel = await getWorkspacePlatformChannelClient(identity);
            return channel.dispatch(WorkspacePlatformChannelAction.ApplyWorkspace, {
                ...workspace,
                options
            });
        },
        restoreLastSavedWorkspace: async (
            options?: ApplyWorkspaceOptions
        ): Promise<RestoreLastSavedWorkspaceResult> => {
            const channel = await getWorkspacePlatformChannelClient(identity);
            return channel.dispatch(WorkspacePlatformChannelAction.RestoreLastSavedWorkspaceInternal, options);
        },
        setActiveWorkspace: async (workspace: Workspace): Promise<void> => {
            const channel = await getWorkspacePlatformChannelClient(identity);
            return channel.dispatch(WorkspacePlatformChannelAction.SetActiveWorkspace, workspace);
        },
        getLanguage: async (): Promise<Locale> => {
            const channel = await getWorkspacePlatformChannelClient(identity);
            return channel.dispatch(WorkspacePlatformChannelAction.GetLanguage);
        },
        _getLanguageResources: async (): ReturnType<WorkspacePlatformModule['_getLanguageResources']> => {
            const channel = await getWorkspacePlatformChannelClient(identity);
            return channel.dispatch(WorkspacePlatformChannelAction.GetLanguageResourcesInternal);
        },
        setLanguage: async (locale: Locale): Promise<void> => {
            const channel = await getWorkspacePlatformChannelClient(identity);
            return channel.dispatch(WorkspacePlatformChannelAction.SetLanguage, locale);
        },
        _raiseAnalytics: async (events: AnalyticsEventInternal[]) => {
            if (!supportedFeatures) {
                supportedFeatures = await internalGetWorkspacePlatformChannelClient(identity);
            }
            if (typeof supportedFeatures === 'object' && supportedFeatures?.analytics?.isSupported) {
                const client = await getWorkspacePlatformChannelClient(identity);
                return client.dispatch(WorkspacePlatformChannelAction.Analytics, events);
            } else {
                console.log(`Analytics not supported for platform ${identity.uuid}`);
            }
        },
        getNotificationsConfig: async (): Promise<NotificationsCustomManifestOptions | undefined> => {
            console.warn(
                'Notifications config is now part of the platform manifest and is automatically resolved by the notifications API. Do NOT use getNotificationsConfig method as it will not return the correct configuration.'
            );
            return undefined;
        },
        _refreshBookmarksInternal: async () => {
            const client = await getWorkspacePlatformChannelClient(identity);
            return client.dispatch(WorkspacePlatformChannelAction.RefreshBookmarksInternal);
        },
        _launchBookmarkInternal: async (payload: LaunchBookmarkPayload) => {
            const client = await getWorkspacePlatformChannelClient(identity);
            return client.dispatch(WorkspacePlatformChannelAction.LaunchBookmarkInternal, payload);
        },
        _updateDockFavoritesInternal: async (favorites: DockEntry[]) => {
            const client = await getWorkspacePlatformChannelClient(identity);
            return client.dispatch(WorkspacePlatformChannelAction.UpdateDockFavoritesInternal, favorites);
        },
        _updateContentMenuInternal: async (contentMenu: ContentMenuEntry[]) => {
            const client = await getWorkspacePlatformChannelClient(identity);
            return client.dispatch(WorkspacePlatformChannelAction.UpdateContentMenuInternal, contentMenu);
        },
        _launchDockEntryInternal: async (payload: LaunchDockEntryPayload) => {
            const client = await getWorkspacePlatformChannelClient(identity);
            return client.dispatch(WorkspacePlatformChannelAction.LaunchDockEntryInternal, payload);
        },
        _setDockFavoritesInternal: async (favorites: DockEntry[]) => {
            const client = await getWorkspacePlatformChannelClient(identity);
            return client.dispatch(WorkspacePlatformChannelAction.SetDockFavoritesOrderInternal, favorites);
        },
        _setDefaultDockButtonsOrderInternal: async (buttons: DockCompanionButton[]) => {
            const client = await getWorkspacePlatformChannelClient(identity);
            return client.dispatch(WorkspacePlatformChannelAction.SetDefaultDockButtonsOrderInternal, buttons);
        },
        _removeDockFavoriteInternal: async (entry: DockEntry) => {
            const client = await getWorkspacePlatformChannelClient(identity);
            return client.dispatch(WorkspacePlatformChannelAction.RemoveDockFavoriteInternal, entry);
        },
        _addDockFavoriteInternal: async (entry: DockEntry) => {
            const client = await getWorkspacePlatformChannelClient(identity);
            return client.dispatch(WorkspacePlatformChannelAction.AddDockFavoriteInternal, entry);
        },
        _navigateContentMenuInternal: async (id: string) => {
            const client = await getWorkspacePlatformChannelClient(identity);
            return client.dispatch(WorkspacePlatformChannelAction.NavigateContentMenuInternal, id);
        },
        _openDockWorkspacesContextMenuInternal: async () => {
            const client = await getWorkspacePlatformChannelClient(identity);
            return client.dispatch(WorkspacePlatformChannelAction.GetDockWorkspacesContextMenuInternal);
        },
        _handleDockWorkspacesMenuResponseInternal: async (payload: any) => {
            const client = await getWorkspacePlatformChannelClient(identity);
            return client.dispatch(WorkspacePlatformChannelAction.HandleDockWorkspacesMenuResponseInternal, payload);
        },
        _refreshDockCollectionMenuInternal: async (collections: Collection[]) => {
            const client = await getWorkspacePlatformChannelClient(identity);
            return client.dispatch(WorkspacePlatformChannelAction.RefreshDockCollectionMenuInternal, collections);
        },
        _launchCollectionInternal: async (collection: Collection) => {
            const client = await getWorkspacePlatformChannelClient(identity);
            return client.dispatch(WorkspacePlatformChannelAction.LaunchCollectionInternal, collection);
        },
        _focusAndExpandSearchInternal: async () => {
            const client = await getWorkspacePlatformChannelClient(identity);
            return client.dispatch(WorkspacePlatformChannelAction.FocusAndExpandSearchInternal);
        },
        _showAboutPagePopup: async (payload: AboutPageConfig) => {
            return showAboutPagePopup(payload);
        },
        Theme: getThemingApi(identity),
        Browser: getBrowserApi(identity),
        Storage: getStorageApi(identity)
    });

    return platformModule;
};

/**
 * Synchronously returns a Platform object that represents the current platform.
 *
 * ```ts
 * import * as WorkspacePlatform from '@openfin/workspace-platform';
 * // get current Workspace Platform
 * const workspacePlatform = WorkspacePlatform.getCurrentSync();
 * // do something with workspacePlatform. e.g. get snapshot of browser window with pages
 * const snapshot = await workspacePlatform.getSnapshot();
 * ```
 */
export const getCurrentSync = (): WorkspacePlatformModule => wrapSync(fin.me.identity);
