let hostSpecsPromise: ReturnType<typeof fin.System.getHostSpecs> | null = null;

const getCachedHostSpecs = () => {
    if (!hostSpecsPromise) {
        hostSpecsPromise = fin.System.getHostSpecs();
    }
    return hostSpecsPromise;
};

/** @internal Reset cached host specs — only for test isolation */
export const resetHostSpecsCache = () => {
    hostSpecsPromise = null;
};

export const isOSWindows = async () => {
    const hostSpecs = await getCachedHostSpecs();
    const hostName = hostSpecs.name;
    return hostName.toLowerCase().includes('windows');
};

export const isWindows10Or11 = async () => {
    const hostSpecs = await getCachedHostSpecs();
    const hostName = hostSpecs.name.toLowerCase();
    return hostName.includes('windows 10') || hostName.includes('windows 11');
};
