import type OpenFin from '@openfin/core';

import { getCurrentOFApplication } from '@common/utils/application';
import makeDebouncedFunc from '@common/utils/debounce';
import { ResponseModalContent } from '@common/utils/menu-config';
import { resolveAbsolutePath } from '@common/utils/router/base';
import makeSharedEmitter from '@common/utils/shared-emitter';
import type { OptionalExceptFor } from '@common/utils/types';
import { currentOFIdentity, WindowCreationOptionsExtended, WindowName } from '@common/utils/window';

import { getComputedBackgroundColor } from '@common/api/theming';

import { applyDeferShowOptions } from './defer-show';
import { getIsEnterpriseBrowser } from './enterpriseBrowser';
import { randomUUID } from './uuid';

const WINDOW_DEFAULTS: Partial<WindowCreationOptionsExtended> = {
    name: WindowName.BrowserMenu,
    alwaysOnTop: true,
    autoShow: true,
    frame: false,
    resizable: false,
    backgroundColor: '#2f3136',
    smallWindow: true,
    showTaskbarIcon: false,
    backgroundThrottling: false,
    saveWindowState: false
};

function withDefaults<T>(options: T): typeof WINDOW_DEFAULTS & T {
    const optionsWithDefaults = { ...WINDOW_DEFAULTS, ...options };
    optionsWithDefaults.url = resolveAbsolutePath(optionsWithDefaults.url ?? '');

    return optionsWithDefaults;
}

type MenuEventTypes = {
    'response': [ModalResponseEvent];
    'ready': [OpenFin.Identity];
    'update': [string, Partial<OpenFin.Bounds>, string];
    'modal-opened': [string];
    'modal-closed': [string];
    'search-menu-opening': [string];
    'search-menu-closed': [string];
};

export interface ModalResponseEvent {
    data: { actionName: string; data?: { textInputValue?: string } };
    name: string;
}

export const menuEvents = makeSharedEmitter<MenuEventTypes>('window.menu');

const setOpacity = (id: OpenFin.Identity, n: number) => fin.Window.wrapSync(id).updateOptions({ opacity: n });

const emitModalResponseInternal = (ev: ModalResponseEvent) => menuEvents.emit('response', ev);

export const emitMenuResponse = (data: ModalResponseEvent['data']) =>
    emitModalResponseInternal({ name: currentOFIdentity.name, data });

type WindowOptionsWithBounds = OptionalExceptFor<OpenFin.WindowOptions, 'name' | 'url'> & { top: number; left: number };
type ModalWindowOptions = WindowOptionsWithBounds & { preventBlur?: boolean; closeOnResponse?: boolean };

const getChildWindows = makeDebouncedFunc(() => getCurrentOFApplication().getChildWindows(), 500);

async function getChildWindow(windowName: string) {
    const windows = await getChildWindows();
    return windows.find((w) => w.identity.name === windowName);
}

const createChildWinPromises: Map<string, Promise<OpenFin.Window | null>> = new Map();

/* We want to close save-enabled modals when they are blurred to avoid flashing when they are reopened.
 * If a save-enabled modal is blurred because the submit/save button was pressed, we do not want to close it immediately.
 * We need to wait until the operation completes before closing the modal. This closing is handled in the respective modal components.
 */
const isSaveEnabledModal = (windowName: string) =>
    [WindowName.BrowserSaveMenu, WindowName.DockSaveWorkspaceMenu, WindowName.DesktopSignalsModal].includes(
        windowName as WindowName
    );

export async function createChildWindow(
    opts: OptionalExceptFor<OpenFin.WindowOptions, 'name' | 'url'> & { preventBlur?: boolean },
    route?: string,
    bounds?: Partial<OpenFin.Bounds>
): Promise<OpenFin.Window> {
    const windowOptions = withDefaults(opts);
    windowOptions.backgroundColor = await getComputedBackgroundColor(fin.me.identity);

    if (!createChildWinPromises.has(windowOptions.name)) {
        const returnPromise = new Promise((res) => {
            // Rather than sending the update event, handle showing window here
            // This makes it so that the window doesn't get shown on reload
            menuEvents.once('ready', async (identity) => {
                if (identity.name === windowOptions.name) {
                    const childWin = await (createChildWinPromises.get(windowOptions.name) as Promise<OpenFin.Window>);

                    if (!windowOptions.preventBlur) {
                        childWin.once('blurred', async () => {
                            setOpacity(identity, 0);
                            childWin.hide();
                            emitModalResponseInternal({ name: windowOptions.name, data: { actionName: 'Cancel' } });

                            if (isSaveEnabledModal(childWin.identity.name)) {
                                const childWindowOptions = await childWin.getOptions();
                                if (
                                    childWindowOptions.customContext !== 'submitting' &&
                                    childWindowOptions.customContext !== 'error'
                                ) {
                                    childWin.close();
                                }
                            } else if (childWin.identity.name.startsWith(WindowName.BrowserMenu)) {
                                childWin.close();
                            }
                        });
                    }

                    // This setTimeout to ensure the opacity is actually set to 1.
                    setTimeout(async () => {
                        await setOpacity(identity, 1);
                        const wOpts = await fin.Window.wrapSync(identity).getOptions();
                        if (wOpts.opacity !== 1) {
                            setOpacity(identity, 1);
                        }
                    });
                    res(childWin);
                }
            });
            const createWindowPromise = (async () => {
                const childWindow = await fin.Platform.getCurrentSync().createWindow(
                    applyDeferShowOptions(
                        {
                            ...windowOptions,
                            opacity: 0,
                            url: route || windowOptions.url,
                            defaultLeft: bounds?.left,
                            defaultTop: bounds?.top,
                            defaultWidth: bounds?.width,
                            defaultHeight: bounds?.height,
                            workspacePlatform: {
                                preventBlur: opts.preventBlur
                            }
                        },
                        true
                    )
                );

                childWindow.once('closed', () => {
                    createChildWinPromises.delete(windowOptions.name);
                });
                return childWindow;
            })();
            createChildWinPromises.set(windowOptions.name, createWindowPromise);
        });
        return returnPromise as Promise<OpenFin.Window>;
    }

    return createChildWinPromises.get(windowOptions.name) as Promise<OpenFin.Window>;
}

async function getUpdatedChildWindowOptions(options: WindowOptionsWithBounds, params: URLSearchParams) {
    const windowOptions: WindowOptionsWithBounds = withDefaults(options);
    const bounds: Partial<OpenFin.Bounds> = {
        top: windowOptions.top,
        left: windowOptions.left,
        width: windowOptions.defaultWidth || windowOptions.width,
        height: windowOptions.defaultHeight || windowOptions.height
    };

    params.set('parentName', fin.Window.getCurrentSync().identity.name);

    return {
        name: windowOptions.name,
        bounds,
        route: `${windowOptions.url}#${params.toString()}`
    };
}

async function updateChildWindow(options: ModalWindowOptions, params: URLSearchParams) {
    const { name, bounds, route } = await getUpdatedChildWindowOptions(options, params);
    const identity = { uuid: fin.me.identity.uuid, name };
    const childWin = fin.Window.wrapSync(identity);
    await Promise.all([childWin.hide(), setOpacity(identity, 0), childWin.setBounds(bounds)]);

    if (!options.preventBlur) {
        childWin.once('blurred', () => {
            setOpacity(identity, 0);
            childWin.hide();
            emitModalResponseInternal({ name: identity.name, data: { actionName: 'Cancel' } });
        });
    }

    menuEvents.emit('update', name, bounds, route);
    await emitModalResponseInternal({ name, data: { actionName: 'Cancel' } });
}

export interface ShowChildOptions {
    options: ModalWindowOptions;
    parameters?: URLSearchParams;
}

export interface ResponseModalOptions {
    options: ModalWindowOptions;
    content: ResponseModalContent;
    parameters?: URLSearchParams;
}

export async function createMenuPosition(
    windowOptions: OptionalExceptFor<OpenFin.WindowOptions, 'x' | 'y'>
): Promise<{ top: number; left: number }> {
    const { x, y } = windowOptions;
    let { top, left } = await fin.Window.getCurrentSync().getBounds();
    const state = fin.me.isWindow && (await fin.me.getState());
    if (state === 'maximized') {
        /* eslint-disable-next-line @typescript-eslint/ban-ts-comment */
        // @ts-ignore
        top = screen.availTop;
        /* eslint-disable-next-line @typescript-eslint/ban-ts-comment */
        // @ts-ignore
        left = screen.availLeft;
    }
    const menuPosition = {
        top: Math.round(top + y + 1),
        left: Math.round(left + x)
    };
    return menuPosition;
}

export async function showChildWindow({ options, parameters }: ShowChildOptions): Promise<OpenFin.Window> {
    // Notify modal state before showing (must happen before focus events fire)
    menuEvents.emit('modal-opened', options.name);

    const updateParameters = parameters ?? new URLSearchParams();
    const windowOptions = withDefaults(options);
    const { name, modalParentIdentity } = windowOptions;

    // If isEnterprise flag query param has already been set (e.g. in workspace modal getter), don't call isEnterpriseBrowser again
    if (!updateParameters.has('isEnterprise')) {
        const isParentEnterprise = `${await getIsEnterpriseBrowser(modalParentIdentity)}`;
        updateParameters.set('isEnterprise', isParentEnterprise);
    }

    let menuWindow = await getChildWindow(name);

    if (!menuWindow) {
        const { route: newRoute, bounds: newBounds } = await getUpdatedChildWindowOptions(options, updateParameters);
        menuWindow = await createChildWindow({ ...windowOptions }, newRoute, newBounds);
    } else {
        await updateChildWindow(windowOptions, updateParameters);
    }

    return menuWindow;
}

const RESPONSE_MODAL_DEFAULTS: Partial<ModalWindowOptions> = {
    shadow: true
};

export const waitForModalResponse = async ({
    options,
    content,
    parameters
}: ResponseModalOptions): Promise<{ data: ModalResponseEvent['data'] }> => {
    const updatedParameters = parameters ?? new URLSearchParams();
    updatedParameters.set('content', JSON.stringify({ ...content, invocationId: randomUUID() }));

    const updatedOptions = {
        ...RESPONSE_MODAL_DEFAULTS,
        ...options,
        name: `${options.name}--${options.modalParentIdentity?.name ?? ''}`
    };

    const modal = await showChildWindow({ options: updatedOptions, parameters: updatedParameters });
    return new Promise((res) => {
        menuEvents.once('response', async (payload) => {
            if (payload.name === updatedOptions.name) {
                res({ data: payload.data });
                if (updatedOptions?.closeOnResponse) {
                    modal.close();
                }
            }
        });
    });
};
