import { FC, useEffect, useState } from 'react';

import { ThemeProvider as BaseThemeProvider, ThemeProviderProps as BaseThemeProviderProps } from '@openfin/ui-library';

import { getOverrides } from '@common/api/overrides';
import { WorkspaceThemeSet } from '@common/api/theming';

import GlobalStyles from '@common/styles/globals';
import GlobalImages from '@common/styles/images';

export interface ThemeProviderProps extends BaseThemeProviderProps {
    themes?: WorkspaceThemeSet;
}

const ThemeProvider: FC<ThemeProviderProps> = ({ children, ...args }) => {
    const [iconUrl, setIconUrl] = useState('');

    const updateIconUrl = async () => {
        const customIconUrl = (await getOverrides()).style?.iconUrl;
        if (customIconUrl) {
            setIconUrl(customIconUrl);
        }
    };

    useEffect(() => {
        updateIconUrl();
    }, []);

    return (
        <BaseThemeProvider {...args}>
            <>
                <GlobalStyles />
                <GlobalImages iconUrl={iconUrl} />
                {children}
            </>
        </BaseThemeProvider>
    );
};

export default ThemeProvider;
