import { createContext, useCallback, useContext, useEffect, useMemo, useState } from 'react';

import { isEnterpriseBrowser } from '@common/utils/enterpriseBrowser';
import { isFin } from '@common/utils/env';

import { getChannelClient } from '@common/api/protocol/workspace';
import {
    getProviders,
    ProviderConnectionPayload,
    ProviderDisconnectionPayload,
    ProviderInfoInternal,
    ProviderType,
    ProviderUpdateEventPayload
} from '@common/api/provider';
import { addListener, removeListener } from '@common/api/workspace-events';

export type ProviderContext<T extends ProviderType = any> = {
    /**
     * The currently active provider.
     */
    activeProvider: ProviderInfoInternal<T> | undefined;
    /**
     * Sets the active provider.
     * @param provider The provider to set as active.
     */
    setActiveProvider: (provider: ProviderInfoInternal<T>) => void;
    /**
     * All providers currently available.
     */
    providers: ProviderInfoInternal<T>[];
    /**
     * Updates a provider.
     * Dispatches a channel action back to the Workspace Provider.
     *
     * @param updatedProvider The updated provider.
     * @returns A promise that resolves when the provider has been updated.
     */
    updateProvider: (updatedProvider: ProviderInfoInternal<T>) => Promise<void>;
};

const isProviderEqual = (a: ProviderInfoInternal, b: ProviderInfoInternal) => {
    return a.uniqueId === b.uniqueId;
};

const PlatformProvidersContext = createContext<ProviderContext>({
    activeProvider: undefined,
    setActiveProvider: () => {
        throw new Error('setActiveProvider must be used within a `ProviderContext` component');
    },
    providers: [],
    updateProvider: () => {
        throw new Error('handleUpdateProviders must be used within a ActiveProviderContextComponent');
    }
});

/**
 * A hook that returns data related to the active provider, and all providers
 *
 * A generic **must** be provided to specify the type of provider to return
 *
 * @example
 * ```ts
 * const { activeProvider, setActiveProvider, providers } = usePlatformProviders<'dock'>();
 * ```
 */
export const usePlatformProviders = <T extends ProviderType = never>(): T extends never
    ? never
    : ProviderContext<T> => {
    const ctx = useContext(PlatformProvidersContext);

    return ctx as T extends never ? never : ProviderContext<T>;
};

/*
 * A component that provides data related to the active provider, and all providers
 */
export const ProviderContext = <T extends ProviderType>({
    children,
    providerType
}: {
    children?: React.ReactNode;
    providerType: T;
}) => {
    const [providers, setProviders] = useState<ProviderInfoInternal<T>[]>([]);
    const [activeProvider, setActiveProvider] = useState<string | undefined>();

    useEffect(() => {
        getProviders(providerType).then((p) => {
            setProviders(p);
            setActiveProvider(p[0]?.uniqueId);
        });
    }, [providerType]);

    useEffect(() => {
        const disconnectListener = async (payload: ProviderDisconnectionPayload) => {
            if (payload.providerType !== providerType) {
                return;
            }

            const filteredProviders = providers.filter((provider) => !isProviderEqual(provider, payload.provider));

            setProviders(filteredProviders);

            if (activeProvider === payload.provider.uniqueId) {
                setActiveProvider(filteredProviders[0]?.uniqueId);
            }
        };

        const connectListener = async (payload: ProviderConnectionPayload) => {
            if (payload.providerType !== providerType) {
                return;
            }

            const p = payload.provider as ProviderInfoInternal<T>;
            if (!providers.some((provider) => isProviderEqual(provider, p))) {
                setProviders((currentProviders) => [...currentProviders, p]);
            }
        };

        const updateListener = async (payload: ProviderUpdateEventPayload) => {
            if (payload.providerType !== providerType) {
                return;
            }

            const newProvider = payload.provider;
            setProviders((currentProviders) =>
                currentProviders.map((provider) => (isProviderEqual(provider, newProvider) ? newProvider : provider))
            );
        };

        addListener('provider-connected', connectListener);
        addListener('provider-disconnected', disconnectListener);
        addListener('provider-updated', updateListener);

        return () => {
            removeListener('provider-connected', connectListener);
            removeListener('provider-disconnected', disconnectListener);
            removeListener('provider-updated', updateListener);
        };
    }, [activeProvider, providerType, providers]);

    const handleSetActiveProvider = useCallback((provider: ProviderInfoInternal<T>) => {
        setActiveProvider(provider.uniqueId);
    }, []);

    const handleUpdateProvider = useCallback(
        async (provider: ProviderInfoInternal<T>) => {
            setProviders((currentProviders) =>
                currentProviders.map((p) => (isProviderEqual(p, provider) ? provider : p))
            );

            const channel = await getChannelClient();

            return channel.dispatch('update-provider', {
                providerType: providerType,
                provider: {
                    ...providers.find((p) => p.uniqueId === activeProvider),
                    ...provider
                }
            } as ProviderUpdateEventPayload);
        },
        [providerType, providers, activeProvider]
    );

    const activeProviderObj = useMemo(
        () => providers.find((p) => p.uniqueId === activeProvider),
        [providers, activeProvider]
    );

    const value = useMemo(
        () => ({
            activeProvider: activeProviderObj,
            setActiveProvider: handleSetActiveProvider,
            providers: providers as ProviderInfoInternal<any>[],
            updateProvider: handleUpdateProvider
        }),
        [activeProviderObj, handleSetActiveProvider, providers, handleUpdateProvider]
    );

    return <PlatformProvidersContext.Provider value={value}>{children}</PlatformProvidersContext.Provider>;
};

export const BrowserTypeContext = createContext<{
    isEnterprise?: boolean | null;
}>({});
export const BrowserLayoutDragContext = createContext<{
    isAcceptingLayoutDrag: boolean;
    setIsAcceptingLayoutDrag: (value: boolean) => void;
}>({
    isAcceptingLayoutDrag: true,
    setIsAcceptingLayoutDrag: () => {
        throw new Error('setIsAcceptingLayoutDrag must be provided within `BrowserContext` component');
    }
});

export const BrowserContext = ({ children }: { children?: React.ReactNode }) => {
    const [isEnterprise, setIsEnterprise] = useState<boolean>(null);
    const [isAcceptingLayoutDrag, setIsAcceptingLayoutDrag] = useState<boolean>(true);

    useEffect(() => {
        if (isFin && fin.me.isWindow) {
            isEnterpriseBrowser().then((val) => setIsEnterprise(val));
        }
    }, []);

    const browserTypeValue = useMemo(() => ({ isEnterprise }), [isEnterprise]);
    const layoutDragValue = useMemo(
        () => ({ isAcceptingLayoutDrag, setIsAcceptingLayoutDrag }),
        [isAcceptingLayoutDrag]
    );

    return (
        <BrowserTypeContext.Provider value={browserTypeValue}>
            <BrowserLayoutDragContext.Provider value={layoutDragValue}>{children}</BrowserLayoutDragContext.Provider>
        </BrowserTypeContext.Provider>
    );
};
