import type OpenFin from '@openfin/core';

import { isFin, isWindowDefined, workspaceBuildVersion } from './env';

/**
 * Promise used to ensure that the window is loaded before calling channel APIs.
 */
const docLoadPromise =
    isWindowDefined &&
    document.readyState !== 'complete' &&
    new Promise<void>((res) =>
        document.addEventListener('readystatechange', () => {
            if (document.readyState === 'complete') {
                res();
            }
        })
    );

export type withDisconnectListener<T> = T & {
    addDisconnectionListener: (listener: () => void) => void;
};

/**
 * Make a function that connects to a channel.
 * If already connected to the channel, will return the channel connection.
 * If disconnected from the channel, will automatically reconnect.
 * @param channelName the name of the channel to connect to.
 * @returns the function to connect to the channel.
 */
export default function makeGetChannelClient(channelName: string) {
    let channelPromise: Promise<withDisconnectListener<OpenFin.ChannelClient>> | undefined;
    const channelDisconnectListeners = new Set<() => void>();

    const connectToChannel = async () => {
        await docLoadPromise;
        const connectPayload = { clientAPIVersion: workspaceBuildVersion };
        const channel = await fin.InterApplicationBus.Channel.connect(channelName, { payload: connectPayload });

        channel.onDisconnection(async () => {
            channelDisconnectListeners.forEach((listener) => listener());
            channelDisconnectListeners.clear();
            console.warn(`disconnected from channel provider ${channelName}`);
            channelPromise = undefined;
        });

        return channel;
    };

    return () => {
        if (!isFin) {
            throw new Error(
                'getChannelClient cannot be used outside an OpenFin env. Avoid using this method during pre-rendering.'
            );
        }
        if (!channelPromise) {
            console.debug(`connecting to channel provider ${channelName}`);
            channelPromise = connectToChannel()
                .then((r) => {
                    console.debug(`connected to channel provider ${channelName}`, r);
                    (r as withDisconnectListener<OpenFin.ChannelClient>).addDisconnectionListener = (
                        listener: () => void
                    ) => {
                        channelDisconnectListeners.add(listener);
                    };
                    return r as any as withDisconnectListener<OpenFin.ChannelClient>;
                })
                .catch((err) => {
                    channelPromise = undefined;
                    throw new Error(`failed to connect to channel provider ${channelName}: ${err}`);
                }) as Promise<withDisconnectListener<OpenFin.ChannelClient>>;
        }
        return channelPromise;
    };
}
