/**
 * Theme migration utilities for backward compatibility.
 *
 * These mapping functions convert between the legacy palette-based theme format
 * (used by workspace platforms v23.0.22 and earlier) and the token-based theme
 * system powered by @openfin/theme-engine.
 *
 * Functions are consumed by both:
 * - client-api-platform (platform init — `initialiseStoragePalettes`)
 * - common (workspace app fallback — `getThemeData` legacy path)
 */
import { parseColorToRgbWithAlpha } from '@common/utils/theming';

import { generateTheme } from '@openfin/theme-engine';

import type {
    BaseThemeOptions,
    CustomPaletteSet,
    CustomTheme,
    CustomThemes,
    GeneratedPalettes,
    GenerateThemeParams
} from './theming';
import { constructThemePaletteSheet, DefaultOpenFinTheme, OpenFinDarkTheme, OpenFinLightTheme } from './theming';

export const assignIfDefined = (target: Record<string, unknown>, key: string, value: unknown) => {
    if (value !== undefined) {
        target[key] = value;
    }
};

/**
 * Maps a legacy palette-based theme to theme-engine seed + overrides.
 *
 * Legacy themes use `palette` (single scheme) or `palettes` (light/dark) with
 * explicit color values. This function translates those values into the dotted
 * token paths that `generateTheme` expects.
 *
 * Mapping reference: https://www.figma.com/design/bUbUpAHJl8xGEtFbpYZ5z3/Theme?node-id=0-1&p=f&m=dev
 */
export const mapLegacyThemeToCustomTheme = (legacyTheme: CustomTheme): GenerateThemeParams => {
    const seed: GenerateThemeParams[0] = {};
    const overrides: GenerateThemeParams[1] = {
        light: {},
        dark: {}
    };

    // Mapping determined via https://www.figma.com/design/bUbUpAHJl8xGEtFbpYZ5z3/Theme?node-id=0-1&p=f&m=dev
    if ('palette' in legacyTheme) {
        const palette = legacyTheme.palette;
        // Base Colors
        assignIfDefined(seed, 'brand.base.dark', palette.background1);
        assignIfDefined(seed, 'brand.accent.dark', palette.brandPrimary);
        assignIfDefined(seed, 'brand.base.light', palette.textDefault);
        assignIfDefined(seed, 'brand.accent.light', palette.brandPrimary);

        // Background Colors
        assignIfDefined(seed, 'color.role.background.1', palette.background1);
        assignIfDefined(seed, 'color.role.background.2', palette.background2);
        assignIfDefined(seed, 'color.role.background.3', palette.background3);
        assignIfDefined(seed, 'color.role.background.4', palette.background4);
        assignIfDefined(seed, 'color.role.background.5', palette.background5);
        assignIfDefined(seed, 'color.role.background.6', palette.background6);
        assignIfDefined(seed, 'color.role.background.accent.base', palette.brandPrimary);
        assignIfDefined(seed, 'color.shared.button.default.background.default', palette.brandSecondary);

        // Buttons
        assignIfDefined(seed, 'color.shared.button.primary.background.default', palette.brandPrimary);
        assignIfDefined(seed, 'color.shared.button.primary.background.pressed', palette.brandPrimaryActive);
        assignIfDefined(seed, 'color.role.background.accent.strong', palette.brandPrimaryHover);
        assignIfDefined(seed, 'color.shared.button.primary.background.hover', palette.brandPrimaryHover);
        assignIfDefined(seed, 'color.role.foreground.onPrimary', palette.brandPrimaryText);
        assignIfDefined(seed, 'color.shared.button.primary.text.default', palette.brandPrimaryText);
        assignIfDefined(seed, 'color.shared.button.default.background.default', palette.brandSecondary);
        assignIfDefined(seed, 'color.role.transparent.18', palette.brandSecondaryActive);
        assignIfDefined(seed, 'color.shared.button.default.background.pressed', palette.brandSecondaryActive);
        assignIfDefined(seed, 'color.shared.button.default.background.hover', palette.brandSecondaryHover);
        assignIfDefined(seed, 'color.shared.button.default.text.default', palette.brandSecondaryText);

        // Inputs
        assignIfDefined(seed, 'color.shared.form.background.default', palette.inputBackground);
        assignIfDefined(seed, 'color.shared.form.value.filled', palette.inputColor);
        assignIfDefined(seed, 'color.shared.form.placeholder.default', palette.inputPlaceholder);
        assignIfDefined(seed, 'color.shared.form.border.focus', palette.inputFocused);
        assignIfDefined(seed, 'color.role.border.base', palette.background5);
        assignIfDefined(seed, 'color.shared.form.border.default', palette.inputBorder);

        // Status
        assignIfDefined(seed, 'color.role.identifier.green', palette.statusSuccess);
        assignIfDefined(seed, 'color.role.identifier.yellow', palette.statusWarning);
        assignIfDefined(seed, 'color.role.identifier.red', palette.statusCritical);

        // Text
        assignIfDefined(seed, 'color.role.foreground.base', palette.textDefault);
        assignIfDefined(seed, 'color.role.foreground.soft', palette.textHelp);
        assignIfDefined(seed, 'color.role.foreground.softer', palette.textInactive);

        // Border
        assignIfDefined(seed, 'color.shared.form.border.focus', palette.borderNeutral);

        // Links
        assignIfDefined(seed, 'color.role.link.default', palette.linkDefault);
        assignIfDefined(seed, 'color.role.link.hover', palette.linkHover);

        // Icons
        assignIfDefined(overrides.light, 'icon.symbol', legacyTheme?.brand?.icons?.light?.symbol);
        assignIfDefined(overrides.dark, 'icon.symbol', legacyTheme?.brand?.icons?.dark?.symbol);
        assignIfDefined(overrides.light, 'icon.wordmark', legacyTheme?.brand?.icons?.light?.wordmark);
        assignIfDefined(overrides.dark, 'icon.wordmark', legacyTheme?.brand?.icons?.dark?.wordmark);
    }
    if ('palettes' in legacyTheme) {
        const { dark: darkPalette, light: lightPalette } = legacyTheme.palettes;
        // Base Colors
        assignIfDefined(seed, 'brand.base.dark', darkPalette.background1);
        assignIfDefined(seed, 'brand.accent.dark', darkPalette.brandPrimary);
        assignIfDefined(seed, 'brand.base.light', darkPalette.textDefault);
        assignIfDefined(seed, 'brand.accent.light', lightPalette.brandPrimary);

        // Dark Palette
        // Background Colors
        assignIfDefined(overrides.dark, 'color.role.background.1', darkPalette.background1);
        assignIfDefined(overrides.dark, 'color.role.background.2', darkPalette.background2);
        assignIfDefined(overrides.dark, 'color.role.background.3', darkPalette.background3);
        assignIfDefined(overrides.dark, 'color.role.background.4', darkPalette.background4);
        assignIfDefined(overrides.dark, 'color.role.background.5', darkPalette.background5);
        assignIfDefined(overrides.dark, 'color.role.background.6', darkPalette.background6);
        assignIfDefined(overrides.dark, 'color.role.background.accent.base', darkPalette.brandPrimary);
        assignIfDefined(overrides.dark, 'color.shared.button.default.background.default', darkPalette.brandSecondary);

        // Buttons
        assignIfDefined(overrides.dark, 'color.shared.button.primary.background.default', darkPalette.brandPrimary);
        assignIfDefined(
            overrides.dark,
            'color.shared.button.primary.background.pressed',
            darkPalette.brandPrimaryActive
        );
        assignIfDefined(overrides.dark, 'color.role.background.accent.strong', darkPalette.brandPrimaryHover);
        assignIfDefined(overrides.dark, 'color.shared.button.primary.background.hover', darkPalette.brandPrimaryHover);
        assignIfDefined(overrides.dark, 'color.role.foreground.onPrimary', darkPalette.brandPrimaryText);
        assignIfDefined(overrides.dark, 'color.shared.button.primary.text.default', darkPalette.brandPrimaryText);
        assignIfDefined(overrides.dark, 'color.shared.button.default.background.default', darkPalette.brandSecondary);
        assignIfDefined(overrides.dark, 'color.role.transparent.18', darkPalette.brandSecondaryActive);
        assignIfDefined(
            overrides.dark,
            'color.shared.button.default.background.pressed',
            darkPalette.brandSecondaryActive
        );
        assignIfDefined(
            overrides.dark,
            'color.shared.button.default.background.hover',
            darkPalette.brandSecondaryHover
        );
        assignIfDefined(overrides.dark, 'color.shared.button.default.text.default', darkPalette.brandSecondaryText);

        // Inputs
        assignIfDefined(overrides.dark, 'color.shared.form.background.default', darkPalette.inputBackground);
        assignIfDefined(overrides.dark, 'color.shared.form.value.filled', darkPalette.inputColor);
        assignIfDefined(overrides.dark, 'color.shared.form.placeholder.default', darkPalette.inputPlaceholder);
        assignIfDefined(overrides.dark, 'color.shared.form.border.focus', darkPalette.inputFocused);
        assignIfDefined(overrides.dark, 'color.role.border.base', darkPalette.background5);
        assignIfDefined(overrides.dark, 'color.shared.form.border.default', darkPalette.inputBorder);

        // Status
        assignIfDefined(overrides.dark, 'color.role.identifier.green', darkPalette.statusSuccess);
        assignIfDefined(overrides.dark, 'color.role.identifier.yellow', darkPalette.statusWarning);
        assignIfDefined(overrides.dark, 'color.role.identifier.red', darkPalette.statusCritical);

        // Text
        assignIfDefined(overrides.dark, 'color.role.foreground.base', darkPalette.textDefault);
        assignIfDefined(overrides.dark, 'color.role.foreground.soft', darkPalette.textHelp);
        assignIfDefined(overrides.dark, 'color.role.foreground.softer', darkPalette.textInactive);

        // Border
        assignIfDefined(overrides.dark, 'color.shared.form.border.focus', darkPalette.borderNeutral);

        // Links
        assignIfDefined(overrides.dark, 'color.role.link.default', darkPalette.linkDefault);
        assignIfDefined(overrides.dark, 'color.role.link.hover', darkPalette.linkHover);

        // Light Palette
        // Background Colors
        assignIfDefined(overrides.light, 'color.role.background.1', lightPalette.background1);
        assignIfDefined(overrides.light, 'color.role.background.2', lightPalette.background2);
        assignIfDefined(overrides.light, 'color.role.background.3', lightPalette.background3);
        assignIfDefined(overrides.light, 'color.role.background.4', lightPalette.background4);
        assignIfDefined(overrides.light, 'color.role.background.5', lightPalette.background5);
        assignIfDefined(overrides.light, 'color.role.background.6', lightPalette.background6);
        assignIfDefined(overrides.light, 'color.role.background.accent.base', lightPalette.brandPrimary);
        assignIfDefined(overrides.light, 'color.shared.button.default.background.default', lightPalette.brandSecondary);

        // Buttons
        assignIfDefined(overrides.light, 'color.shared.button.primary.background.default', lightPalette.brandPrimary);
        assignIfDefined(
            overrides.light,
            'color.shared.button.primary.background.pressed',
            lightPalette.brandPrimaryActive
        );
        assignIfDefined(overrides.light, 'color.role.background.accent.strong', lightPalette.brandPrimaryHover);
        assignIfDefined(
            overrides.light,
            'color.shared.button.primary.background.hover',
            lightPalette.brandPrimaryHover
        );
        assignIfDefined(overrides.light, 'color.role.foreground.onPrimary', lightPalette.brandPrimaryText);
        assignIfDefined(overrides.light, 'color.shared.button.primary.text.default', lightPalette.brandPrimaryText);
        assignIfDefined(overrides.light, 'color.shared.button.default.background.default', lightPalette.brandSecondary);
        assignIfDefined(overrides.light, 'color.role.transparent.18', lightPalette.brandSecondaryActive);
        assignIfDefined(
            overrides.light,
            'color.shared.button.default.background.pressed',
            lightPalette.brandSecondaryActive
        );
        assignIfDefined(
            overrides.light,
            'color.shared.button.default.background.hover',
            lightPalette.brandSecondaryHover
        );
        assignIfDefined(overrides.light, 'color.shared.button.default.text.default', lightPalette.brandSecondaryText);

        // Inputs
        assignIfDefined(overrides.light, 'color.shared.form.background.default', lightPalette.inputBackground);
        assignIfDefined(overrides.light, 'color.shared.form.value.filled', lightPalette.inputColor);
        assignIfDefined(overrides.light, 'color.shared.form.placeholder.default', lightPalette.inputPlaceholder);
        assignIfDefined(overrides.light, 'color.shared.form.border.focus', lightPalette.inputFocused);
        assignIfDefined(overrides.light, 'color.role.border.base', lightPalette.background5);
        assignIfDefined(overrides.light, 'color.shared.form.border.default', lightPalette.inputBorder);

        // Status
        assignIfDefined(overrides.light, 'color.role.identifier.green', lightPalette.statusSuccess);
        assignIfDefined(overrides.light, 'color.role.identifier.yellow', lightPalette.statusWarning);
        assignIfDefined(overrides.light, 'color.role.identifier.red', lightPalette.statusCritical);

        // Text
        assignIfDefined(overrides.light, 'color.role.foreground.base', lightPalette.textDefault);
        assignIfDefined(overrides.light, 'color.role.foreground.soft', lightPalette.textHelp);
        assignIfDefined(overrides.light, 'color.role.foreground.softer', lightPalette.textInactive);

        // Border
        assignIfDefined(overrides.light, 'color.shared.form.border.focus', lightPalette.borderNeutral);

        // Links
        assignIfDefined(overrides.light, 'color.role.link.default', lightPalette.linkDefault);
        assignIfDefined(overrides.light, 'color.role.link.hover', lightPalette.linkHover);

        // Icons
        assignIfDefined(overrides.light, 'icon.symbol', legacyTheme?.brand?.icons?.light?.symbol);
        assignIfDefined(overrides.dark, 'icon.symbol', legacyTheme?.brand?.icons?.dark?.symbol);
        assignIfDefined(overrides.light, 'icon.wordmark', legacyTheme?.brand?.icons?.light?.wordmark);
        assignIfDefined(overrides.dark, 'icon.wordmark', legacyTheme?.brand?.icons?.dark?.wordmark);
    }
    if ('brand' in legacyTheme) {
        assignIfDefined(overrides.light, 'icon.symbol', legacyTheme?.brand?.icons?.light?.symbol);
        assignIfDefined(overrides.dark, 'icon.symbol', legacyTheme?.brand?.icons?.dark?.symbol);
        assignIfDefined(overrides.light, 'icon.wordmark', legacyTheme?.brand?.icons?.light?.wordmark);
        assignIfDefined(overrides.dark, 'icon.wordmark', legacyTheme?.brand?.icons?.dark?.wordmark);
    }
    return [seed, overrides];
};

/**
 * Reverse of mapLegacyThemeToCustomTheme.
 * Takes the resolved token maps from a generated theme and maps them back to the
 * legacy CustomPaletteSet shape so that workspace apps still on the legacy theme
 * system can consume them.
 */
export const mapGeneratedPalettesToLegacyPalettes = (
    generatedPalettes: GeneratedPalettes
): { light: CustomPaletteSet; dark: CustomPaletteSet } => {
    const mapScheme = (tokens: GeneratedPalettes['light'] | GeneratedPalettes['dark']): CustomPaletteSet => ({
        brandPrimary: tokens['color.shared.button.primary.background.default'] ?? '',
        brandSecondary: tokens['color.shared.button.default.background.default'] ?? '',
        backgroundPrimary: tokens['color.role.background.1'] ?? '',

        brandPrimaryActive: tokens['color.shared.button.primary.background.pressed'],
        brandPrimaryHover: tokens['color.shared.button.primary.background.hover'],
        brandPrimaryFocused: tokens['color.role.foreground.onPrimary'],
        brandPrimaryText: tokens['color.shared.button.primary.text.default'],
        brandSecondaryActive: tokens['color.shared.button.default.background.pressed'],
        brandSecondaryHover: tokens['color.shared.button.default.background.hover'],
        brandSecondaryFocused: tokens['color.shared.button.default.text.default'],
        brandSecondaryText: tokens['color.shared.button.default.text.default'],

        statusSuccess: tokens['color.role.identifier.green'],
        statusWarning: tokens['color.role.identifier.yellow'],
        statusCritical: tokens['color.role.identifier.red'],
        statusActive: tokens['color.role.identifier.blue'],

        inputBackground: tokens['color.shared.form.background.default'],
        inputColor: tokens['color.shared.form.value.filled'],
        inputPlaceholder: tokens['color.shared.form.placeholder.default'],
        // 50% opacity to match legacy inputDisabled behavior. Tokens are always
        // resolved to rgb()/rgba() strings by the theme engine, so we use rgba()
        // rather than a hex opacity suffix which would produce invalid CSS.
        inputDisabled: tokens['color.shared.form.value.default']
            ? `rgba(${parseColorToRgbWithAlpha(tokens['color.shared.form.value.default']).rgb}, 0.5)`
            : undefined,
        inputFocused: tokens['color.shared.form.border.focus'],
        inputBorder: tokens['color.shared.form.border.default'],

        textDefault: tokens['color.role.foreground.base'],
        textHelp: tokens['color.role.foreground.soft'],
        textInactive: tokens['color.role.foreground.softer'],

        background1: tokens['color.role.background.1'],
        background2: tokens['color.role.background.2'],
        background3: tokens['color.role.background.3'],
        background4: tokens['color.role.background.4'],
        background5: tokens['color.role.background.5'],
        background6: tokens['color.role.background.6'],

        contentBackground1: tokens['color.role.background.accent.base'],
        contentBackground2: tokens['color.role.background.2'],
        contentBackground3: tokens['color.role.background.3'],
        contentBackground4: tokens['color.role.background.4'],
        contentBackground5: tokens['color.role.background.5'],

        linkDefault: tokens['color.role.link.default'],
        linkHover: tokens['color.role.link.hover'],

        borderNeutral: tokens['color.shared.form.border.focus']
    });

    return {
        light: mapScheme(generatedPalettes.light),
        dark: mapScheme(generatedPalettes.dark)
    };
};

export const mapLegacyBrandIcons = (legacyBrand: BaseThemeOptions['brand']): GenerateThemeParams[1] => {
    const iconOverrides = {
        light: {},
        dark: {}
    };

    assignIfDefined(iconOverrides.light, 'icon.symbol', legacyBrand?.icons?.light?.symbol);
    assignIfDefined(iconOverrides.dark, 'icon.symbol', legacyBrand?.icons?.dark?.symbol);
    assignIfDefined(iconOverrides.light, 'icon.wordmark', legacyBrand?.icons?.light?.wordmark);
    assignIfDefined(iconOverrides.dark, 'icon.wordmark', legacyBrand?.icons?.dark?.wordmark);

    return iconOverrides;
};

/**
 * Converts legacy CustomThemes (from old workspace platforms v23.0.22 and earlier)
 * into GeneratedPalettes with toCSS() methods and a ready-to-inject palette sheet.
 *
 * This is the backward-compatibility bridge: when a new workspace app (home, dock,
 * storefront) discovers it's running against a legacy platform — detected by
 * `getGeneratedPalettes()` throwing because the channel action doesn't exist —
 * it calls `getThemes()` to retrieve the old-format themes and runs them through
 * this function to produce the same output the new pipeline expects.
 *
 * The conversion mirrors `initialiseStoragePalettes` in client-api-platform but
 * omits storage controller side-effects (setPalettes, setThemePaletteSheet) since
 * those belong to the platform init path, not the workspace app consumption path.
 *
 * Theme shape discrimination:
 * - `palette`: single palette applied to both schemes (legacy single-scheme theme)
 * - `palettes`: explicit light/dark palettes (legacy dual-scheme theme)
 * - `seed`: already a token-based theme (should not reach this path, but handled for safety)
 */
export const convertLegacyThemesToGeneratedPalettes = (
    themes: CustomThemes | null | undefined
): { generatedPalettes: GeneratedPalettes; themePaletteSheet: string } => {
    const customThemes = themes?.length ? themes : DefaultOpenFinTheme;
    const theme = customThemes[0];

    if ('seed' in theme) {
        const overrides =
            'brand' in theme ? { ...mapLegacyBrandIcons(theme.brand), ...theme.overrides } : theme.overrides;
        const generatedTheme = generateTheme(theme.seed, overrides);
        const generatedPalettes: GeneratedPalettes = {
            dark: generatedTheme.dark,
            light: generatedTheme.light
        };
        return { generatedPalettes, themePaletteSheet: constructThemePaletteSheet(generatedPalettes) };
    }

    if ('palette' in theme) {
        // Single palette: merge with OpenFin dark defaults so all palette keys are
        // populated, then use the same palette for both light and dark schemes.
        const mergedPalette = { ...OpenFinDarkTheme, ...theme.palette };
        const mergedTheme = { ...theme, palette: mergedPalette };
        const [seed, overrides] = mapLegacyThemeToCustomTheme(mergedTheme);
        const generatedTheme = generateTheme(seed, overrides);
        const generatedPalettes: GeneratedPalettes = {
            dark: generatedTheme.dark,
            light: generatedTheme.light
        };
        return { generatedPalettes, themePaletteSheet: constructThemePaletteSheet(generatedPalettes) };
    }

    if ('palettes' in theme) {
        // Dual palettes: merge each scheme with its respective OpenFin defaults.
        const { dark, light } = theme.palettes;
        const mergedDarkPalette = { ...OpenFinDarkTheme, ...dark };
        const mergedLightPalette = { ...OpenFinLightTheme, ...light };
        const mergedTheme = { ...theme, palettes: { dark: mergedDarkPalette, light: mergedLightPalette } };
        const [seed, overrides] = mapLegacyThemeToCustomTheme(mergedTheme);
        const generatedTheme = generateTheme(seed, overrides);
        const generatedPalettes: GeneratedPalettes = {
            dark: generatedTheme.dark,
            light: generatedTheme.light
        };
        return { generatedPalettes, themePaletteSheet: constructThemePaletteSheet(generatedPalettes) };
    }

    // Fallback: use the default OpenFin theme if no recognized shape is found.
    const [seed, overrides] = mapLegacyThemeToCustomTheme(DefaultOpenFinTheme[0]);
    const generatedTheme = generateTheme(seed, overrides);
    const generatedPalettes: GeneratedPalettes = {
        dark: generatedTheme.dark,
        light: generatedTheme.light
    };
    return { generatedPalettes, themePaletteSheet: constructThemePaletteSheet(generatedPalettes) };
};
