import type OpenFin from '@openfin/core';

import { isWindowMaximized } from '@common/components/IndicatorContainer/bounds';

import { AnchorBehavior } from '@client-platform/api/context-menu';

import { getBoundsBasedOnAnchorBehavior } from './context-menu';
import { ResponseModalConfig } from './menu-config';
import { isWindows10Or11 } from './os';
import {
    getBoundsFromCenter,
    getCenterFromBounds,
    getCenterFromMonitorBounds,
    getMonitorWindowMostOn,
    getOFWindow,
    getPercentageOfBoundsInMonitor,
    Point
} from './window';

/**
 *
 * @param parentWindowIdentity parent window for the modal
 * @returns a point (top/left) that represents the center of the monitor the parent window is on
 */

export const getCenterOfParentWindowMonitor = async (parentWindowIdentity?: OpenFin.Identity): Promise<Point> => {
    const windowBounds = parentWindowIdentity && (await getOFWindow(parentWindowIdentity).getBounds());

    // if no parentWindowIdentity then use the primary monitor
    const monitor = parentWindowIdentity
        ? await getMonitorWindowMostOn(windowBounds)
        : (await fin.System.getMonitorInfo()).primaryMonitor;

    return getCenterFromMonitorBounds(monitor.availableRect);
};

/**
 * returns the correct bounds for the response modal to be displayed at
 * this will return the correct bounds regardless of whether the window is maximized
 *
 * @param modalOptions window options including height/width so that we can calculate the correct bounds
 * @param parentWindowIdentity the window to get the bounds from. If this is undefined, the primary monitor will be used
 * @param centerOnMonitor whether the modal should be centered on the monitor
 * @returns the bounds for where the modal is to be displayed
 */
export const getResponseModalBounds = async (
    modalOptions: Pick<ResponseModalConfig['windowOptions'], 'defaultWidth' | 'defaultHeight'>,
    parentWindowIdentity?: OpenFin.Identity,
    centerOnMonitor = false
): Promise<OpenFin.Bounds> => {
    let targetCenter: Point | undefined;

    if (centerOnMonitor) {
        targetCenter = await getCenterOfParentWindowMonitor(parentWindowIdentity);
    } else {
        const parentWin = getOFWindow(parentWindowIdentity);
        const parentWindowBounds = await parentWin.getBounds();
        targetCenter = getCenterFromBounds(parentWindowBounds);
    }

    const { defaultHeight: height, defaultWidth: width } = modalOptions;

    return getBoundsFromCenter(targetCenter, { height, width });
};

const checkIfBoundsAreOffScreen = async (bounds: OpenFin.Bounds): Promise<boolean> => {
    const finMonitorInfo = await fin.System.getMonitorInfo();
    const allMonitorInfo = [finMonitorInfo.primaryMonitor, ...finMonitorInfo.nonPrimaryMonitors];

    for (const monitor of allMonitorInfo) {
        if (getPercentageOfBoundsInMonitor(bounds, monitor) === 1) {
            return false;
        }
    }

    return true;
};

export async function getResponseModalBoundsAndCenterParentIfModalOffScreen(
    modalOptions: Parameters<typeof getResponseModalBounds>[0],
    parentWindowIdentity?: OpenFin.Identity,
    centerOnMonitor = false,
    // returns bounds relative to the parent window
    relativeBounds = false
): Promise<OpenFin.Bounds> {
    const isParentWindowMaximised =
        parentWindowIdentity && (await getOFWindow(parentWindowIdentity).getState()) === 'maximized';
    const shouldCenterOnMonitor = centerOnMonitor || isParentWindowMaximised || !parentWindowIdentity;
    let responseBounds = await getResponseModalBounds(modalOptions, parentWindowIdentity, shouldCenterOnMonitor);

    if (await checkIfBoundsAreOffScreen(responseBounds)) {
        await getOFWindow(parentWindowIdentity).center();
        responseBounds = await getResponseModalBounds(modalOptions, parentWindowIdentity, shouldCenterOnMonitor);
    } else {
        console.warn("Response modal isn't off screen, not centering parent window");
    }

    if (relativeBounds && parentWindowIdentity) {
        const parentWin = getOFWindow(parentWindowIdentity);
        const parentWindowBounds = await parentWin.getBounds();
        responseBounds.left -= parentWindowBounds.left;
        responseBounds.top -= parentWindowBounds.top;
    }
    return responseBounds;
}

/**
 * Adjusts the given bounds to be within the closest monitor's available bounds if they are offscreen.
 *
 * @param {OpenFin.Bounds} bounds - The bounds to be adjusted.
 * @returns {Promise<OpenFin.Bounds>} - The adjusted bounds that are within the closest monitor's available bounds.
 */
export async function getClosestBoundsIfModalBoundsOffscreen(bounds: OpenFin.Bounds): Promise<OpenFin.Bounds> {
    const targetMonitor = await getMonitorWindowMostOn(bounds);

    if (getPercentageOfBoundsInMonitor(bounds, targetMonitor) === 1) {
        return bounds;
    }

    if (targetMonitor) {
        const monitorBounds = targetMonitor.availableRect;

        // Adjust the bounds to be within the monitor bounds
        const adjustedBounds: OpenFin.Bounds = {
            top: Math.max(monitorBounds.top, Math.min(bounds.top, monitorBounds.bottom - bounds.height)),
            left: Math.max(monitorBounds.left, Math.min(bounds.left, monitorBounds.right - bounds.width)),
            height: bounds.height,
            width: bounds.width
        };

        return adjustedBounds;
    }
}

/**
 * Adjusts the given bounds if they are offscreen to be within the closest monitor's available bounds.
 * Returns bounds relative to the parent window's bounds (as opposed to bounds relative to the monitor).
 *
 * @param {OpenFin.WindowBounds} parentWindowBounds - The bounds of the parent window.
 * @param {OpenFin.Bounds} bounds - The bounds to be adjusted.
 * @returns {Promise<OpenFin.Bounds>} - The adjusted bounds that are within the closest monitor's available bounds relative to the parent window's bounds.
 */
export const getClosestRelativeBoundsIfModalBoundsOffscreen = async (
    parentWindowBounds: OpenFin.WindowBounds,
    bounds: OpenFin.Bounds
): Promise<OpenFin.Bounds> => {
    const monitorRelativeBounds = await getClosestBoundsIfModalBoundsOffscreen({
        height: bounds.height,
        width: bounds.width,
        top: bounds.top + parentWindowBounds.top,
        left: bounds.left + parentWindowBounds.left
    });

    return {
        height: bounds.height,
        width: bounds.width,
        top: monitorRelativeBounds.top - parentWindowBounds.top,
        left: monitorRelativeBounds.left - parentWindowBounds.left
    };
};

/**
 * Returns whether a window is maximized and the OS is Windows 10 or 11.
 * Relates to: https://github.com/electron/electron/issues/4045
 *
 * @param window - The OpenFin window.
 * @returns A promise that resolves to a boolean indicating whether a window is maximized and the OS is Windows 10 or 11.
 */
export const getIsWindowMaximizedOnWindows10Or11 = async (window: OpenFin.Window): Promise<boolean> => {
    return (await isWindows10Or11()) && (await isWindowMaximized(window));
};

/**
 * Retrieves the current bounds of a window whether it's maximized or minimized.
 * For maximized windows on Windows 10 and 11, it will return adjusted bounds to account for an Electron bug where a 7px
 * shadow is included in the measurement of the window bounds.
 *
 * Relates to: https://github.com/electron/electron/issues/4045
 *
 * @param windowIdentity - The identity of the window.
 * @returns A promise that resolves to the current window bounds.
 */
export const getCurrentBounds = async (windowIdentity: OpenFin.Identity): Promise<OpenFin.WindowBounds> => {
    const window = fin.Window.wrapSync(windowIdentity);
    const windowBounds = await window.getBounds({
        boundsType: 'current'
    });

    if (await getIsWindowMaximizedOnWindows10Or11(window)) {
        return {
            top: windowBounds.top + 7,
            left: windowBounds.left + 7,
            right: windowBounds.left + windowBounds.width - 7,
            bottom: windowBounds.top + windowBounds.height - 7,
            height: windowBounds.height - 14,
            width: windowBounds.width - 14,
            content: {
                top: windowBounds.top + 7,
                left: windowBounds.left + 7,
                height: windowBounds.height - 14,
                width: windowBounds.width - 14
            }
        };
    }

    return windowBounds;
};

export async function getBoundsCenteredAndFitOnMonitor(
    height: number,
    width: number,
    monitorRect?: OpenFin.MonitorDetails
) {
    const monitorInfo = await fin.System.getMonitorInfo();
    const rect = monitorRect?.availableRect ?? monitorInfo.primaryMonitor.availableRect;
    const monitorBounds = { width: rect.right - rect.left, height: rect.bottom - rect.top };

    const adjustedHeight = Math.min(height, monitorBounds.height);
    const adjustedWidth = Math.min(width, monitorBounds.width);
    const top = rect.top + Math.floor((monitorBounds.height - adjustedHeight) / 2);
    const left = rect.left + Math.floor((monitorBounds.width - adjustedWidth) / 2);

    return { height: adjustedHeight, width: adjustedWidth, left, top };
}

/**
 * Calculates the final popup bounds relative to a parent window, accounting for:
 * - Windows 10/11 maximized window shadow offset (Electron bug)
 * - Anchor behavior (e.g. BottomRight, TopLeft)
 * - Off-screen clamping to keep the popup within monitor bounds
 *
 * @param parentIdentity - The identity of the parent window.
 * @param contentDimensions - The width and height of the popup content.
 * @param position - The desired x/y position relative to the parent window.
 * @param anchorBehavior - Optional anchor behavior to adjust positioning.
 * @returns Bounds relative to the parent window, clamped to the nearest monitor.
 */
export const getPopupBoundsRelativeToParent = async (
    parentIdentity: OpenFin.Identity,
    contentDimensions: { width: number; height: number },
    position: { x: number; y: number },
    anchorBehavior?: AnchorBehavior
): Promise<OpenFin.Bounds> => {
    const parentWindow = fin.Window.wrapSync(parentIdentity);
    const parentWindowBounds = await parentWindow.getBounds({ boundsType: 'current' });
    const shouldAdjustBounds = await getIsWindowMaximizedOnWindows10Or11(parentWindow);

    const bounds = getBoundsBasedOnAnchorBehavior(
        {
            height: contentDimensions.height,
            width: contentDimensions.width,
            top: shouldAdjustBounds ? position.y + 7 : position.y,
            left: shouldAdjustBounds ? position.x + 7 : position.x
        },
        anchorBehavior
    );

    return getClosestRelativeBoundsIfModalBoundsOffscreen(parentWindowBounds, bounds);
};
