import { createSlice, PayloadAction } from '@reduxjs/toolkit';

import { Menu, UserMenuParams } from '@common/utils/menu';

export interface SystemMenuParams {
    parentName: string;
}

export type CompleteMenuParams<M extends Menu> = UserMenuParams[M] & SystemMenuParams;

interface ActiveState<M extends Menu = Menu> {
    type: M | null;
    params: UserMenuParams[M] | null;
}

export interface InitialState {
    active: ActiveState;
}

export interface MenusRootState {
    menu: InitialState;
}

const initialState: InitialState = {
    active: {
        type: null,
        params: null
    }
};

export const menuSlice = createSlice({
    name: 'menu',
    initialState,
    reducers: {
        openMenu: (state, action: PayloadAction<ActiveState>) => {
            state.active = action.payload;
        },
        closeActiveMenu: (state) => {
            state.active = {
                type: null,
                params: null
            };
        }
    }
});

export const openMenu = <M extends Menu = Menu>(menu: M, params: UserMenuParams[M]) =>
    menuSlice.actions.openMenu({ type: menu, params });

export const { closeActiveMenu } = menuSlice.actions;

export const selectActiveMenu = (state: MenusRootState): ActiveState => state.menu.active;

export default menuSlice.reducer;
