export enum Env {
    Local = 'local',
    Dev = 'dev',
    Staging = 'staging',
    Prod = 'prod'
}

export const isFin = typeof window !== 'undefined' && typeof fin !== 'undefined';
export const isJest = !!(typeof process !== 'undefined' && process.env?.JEST_WORKER_ID);
export const isWindowDefined = typeof window !== 'undefined';
export const isDocumentDefined = typeof document !== 'undefined';
export const isWindowDefinedWithIndexDB = isWindowDefined && typeof indexedDB !== 'undefined';

const windowOrigin = isWindowDefined ? window.origin : Env.Local;
export const finUUID = (isFin && fin.me.uuid) as string;
export const finName = (isFin && fin.me.name) as string;
export const finEntityType = isFin && fin.me.entityType;

export const isEnvLocal = ENV === Env.Local;
export const isEnvDev = ENV === Env.Dev;
export const isEnvStaging = ENV === Env.Staging;
export const isEnvProd = ENV === Env.Prod;

declare const WORKSPACE_PROVIDER_FINS_LINK: string;
export const workspaceProviderFinsLink =
    typeof WORKSPACE_PROVIDER_FINS_LINK !== 'undefined' && WORKSPACE_PROVIDER_FINS_LINK;

declare const WORKSPACE_PROVIDER_FALLBACK_URL: string;
export const workspaceProviderFallbackUrl =
    typeof WORKSPACE_PROVIDER_FALLBACK_URL !== 'undefined' && WORKSPACE_PROVIDER_FALLBACK_URL;

const getAbsoluteUrl = (url: string) => {
    if (url.startsWith('http://') || url.startsWith('https://')) {
        return url;
    }
    return windowOrigin + url;
};

declare const WORKSPACE_CDN_URL: string;
export const workspaceCdnUrl = typeof WORKSPACE_CDN_URL !== 'undefined' && getAbsoluteUrl(WORKSPACE_CDN_URL);

declare const WORKSPACE_CDN_ENV_URL: string;
export const workspaceCdnEnvUrl = typeof WORKSPACE_CDN_ENV_URL !== 'undefined' && getAbsoluteUrl(WORKSPACE_CDN_ENV_URL);

declare const WORKSPACE_DOCS_PLATFORM_URL: string;
export const workspaceDocsPlatformUrl =
    typeof WORKSPACE_DOCS_PLATFORM_URL !== 'undefined' && getAbsoluteUrl(WORKSPACE_DOCS_PLATFORM_URL);

declare const WORKSPACE_DOCS_CLIENT_URL: string;
export const workspaceDocsClientUrl =
    typeof WORKSPACE_DOCS_CLIENT_URL !== 'undefined' && getAbsoluteUrl(WORKSPACE_DOCS_CLIENT_URL);

declare const WORKSPACE_RUNTIME_VERSION: string;
export const workspaceRuntimeVersion = (typeof WORKSPACE_RUNTIME_VERSION !== 'undefined' &&
    WORKSPACE_RUNTIME_VERSION) as string;

declare const WORKSPACE_BUILD_VERSION: string;
export const workspaceBuildVersion = (typeof WORKSPACE_BUILD_VERSION !== 'undefined' &&
    WORKSPACE_BUILD_VERSION) as string;

declare const WORKSPACE_BUILD_SHA: string;
export const workspaceBuildSha = (typeof WORKSPACE_BUILD_SHA !== 'undefined' && WORKSPACE_BUILD_SHA) as string;
