import type OpenFin from '@openfin/core';

import { titleCase } from 'title-case';

import { ViewTabContextMenuTemplate, ViewTabMenuData, ViewTabMenuOptionType } from '@client-platform/shapes';

import { MenuItemType } from './context-menu';

const getIconForColorGroup = (color: string, checked = false): Promise<string> =>
    new Promise((resolve) => {
        let resolvedColor = color;
        const cssVarRegex = /var\((.*)\)/;
        if (cssVarRegex.test(color)) {
            const cssVar = cssVarRegex.exec(color)?.[1];
            resolvedColor = getComputedStyle(document.documentElement).getPropertyValue(cssVar);
        }

        const svgString = `
        <svg width="12" height="12" xmlns="http://www.w3.org/2000/svg">
            <circle cx="6" cy="6" r="6" fill="${resolvedColor}"/>
            ${
                // conditionally add the check mark
                checked &&
                '<path d="M 2.565 6.163 L 3.251 5.477 L 4.968 7.194 L 8.744 3.417 L 9.43 4.104 L 4.968 8.565 Z" style="fill: #fff;stroke-width: 0.5;stroke: white;"/>'
            }
        </svg>`;
        const svg = new Blob([svgString], {
            type: 'image/svg+xml;charset=utf-8'
        });
        const objectUrl = URL.createObjectURL(svg);

        const canvas = document.createElement('canvas');
        canvas.setAttribute('width', '12');
        canvas.setAttribute('height', '12');
        const ctx = canvas.getContext('2d');
        const img = new Image();
        img.onload = () => {
            ctx.drawImage(img, 0, 0);
            const imgURL = canvas.toDataURL('image/png');
            resolve(imgURL);
        };

        img.src = objectUrl;
    });

export const getChannelsMenuOptions = async (
    channelsForViews: string[],
    colorGroups: OpenFin.ContextGroupInfo[]
): Promise<ViewTabContextMenuTemplate[]> => {
    const templateItemsPromises = colorGroups.map(async (colorGroup: OpenFin.ContextGroupInfo) => {
        const areAllViewsInThisChannel = channelsForViews.every((channel) => channel === colorGroup.id.toLowerCase());
        const base64Icon = await getIconForColorGroup(colorGroup.displayMetadata.color, areAllViewsInThisChannel);
        return {
            type: MenuItemType.Label,
            label: titleCase(colorGroup.displayMetadata.name),
            data: { type: ViewTabMenuOptionType.AddToChannel, option: colorGroup.id } as ViewTabMenuData,
            icon: base64Icon
        };
    });
    return Promise.all(templateItemsPromises);
};

