/**
 * Very smol util intended to be executed ASAP in HTML pages
 * to load and compute the value of theme palette variables from localstorage, and react to
 * any updates to their value.
 *
 * When ran before the first paint, this guarantees the first paint (and subsequent paints)
 * will use the correct palette when StorageThemeProvider is in use, eliminating all flicker.
 *
 * `themeLoader` is turned into a string and executed in a script tag — it cannot reference
 * module imports. Use the inline `log` helper (structured, delegates to console).
 */

type ComputedScheme = 'light' | 'dark';

export const themeLoader = (uuid: string, addListeners = true) => {
    const log = {
        debug(operation: string, message: string, data?: Record<string, unknown>) {
            if (typeof console !== 'undefined' && console.debug) {
                console.debug('[common.StorageThemeProvider.themeLoader]', operation, message, data);
            }
        },
        info(operation: string, message: string, data?: Record<string, unknown>) {
            if (typeof console !== 'undefined' && console.info) {
                console.info('[common.StorageThemeProvider.themeLoader]', operation, message, data);
            }
        },
        error(operation: string, message: string, data?: Record<string, unknown>) {
            if (typeof console !== 'undefined' && console.error) {
                console.error('[common.StorageThemeProvider.themeLoader]', operation, message, data);
            }
        }
    };

    const themeSheet = localStorage.getItem(`${uuid}-ThemePaletteSheet`);
    log.info('themeLoader', 'Theme sheet read from localStorage', {
        uuid,
        sheetPresent: Boolean(themeSheet),
        sheetLength: themeSheet ? themeSheet.length : 0
    });

    const schemeKey = `${uuid}-SelectedColorScheme`;
    const computeScheme = (): ComputedScheme => {
        const savedScheme = localStorage.getItem(schemeKey) as ComputedScheme;
        const savedDefaultScheme = localStorage.getItem(`${uuid}-ThemePaletteDefaultScheme`) as ComputedScheme;

        const systemPrefersDark = window.matchMedia('(prefers-color-scheme: dark)').matches;
        const systemPreferredScheme = systemPrefersDark ? 'dark' : 'light';

        // pick the savedScheme, fallback to either default or system preference
        return savedScheme ?? savedDefaultScheme ?? systemPreferredScheme;
    };

    const sheet = new CSSStyleSheet();
    // applyCSS runs both at startup (when the sheet is already in localStorage) and from the
    // storage listener when a late sheet arrives (the SUPPORT-2481 recovery path). This flag
    // ensures the sheet is pushed into document.adoptedStyleSheets only once.
    let sheetAdopted = false;

    const applyCSS = (css: string) => {
        const trimmedCSS = css.trim();
        log.debug('applyCSS', 'Applying CSS', { cssLength: trimmedCSS.length, adoptingSheet: !sheetAdopted });
        if (!sheetAdopted) {
            document.adoptedStyleSheets = [...document.adoptedStyleSheets, sheet];
            sheetAdopted = true;
            // The sheet may have arrived late via the storage listener (recovery path), in
            // which case the saved scheme keys may have landed alongside it — recompute the
            // scheme. At startup this is redundant but harmless: the same value is applied
            // again at the bottom of themeLoader.
            window.document.documentElement.setAttribute('data-scheme', computeScheme());
        }
        sheet.replaceSync(trimmedCSS);
    };

    if (themeSheet) {
        applyCSS(themeSheet);
    } else {
        // SUPPORT-2481: do NOT return here. The sheet may simply not have been synced yet
        // (the first theme sync is async and can race window creation). Fall through so the
        // storage listeners below are registered and can apply the sheet when it lands.
        log.error('themeLoader', 'No theme sheet found in localStorage', {});
    }

    if (addListeners) {
        window.addEventListener('storage', (e): void => {
            if (e.key && e.key === `${uuid}-ThemePaletteSheet` && e.newValue) {
                try {
                    log.info('storage', 'Theme sheet updated via storage event', {
                        sheetLength: e.newValue.length,
                        recoveredFromMissingSheet: !sheetAdopted
                    });
                    // applyCSS handles both the recovery path (page painted without a sheet
                    // because the sync raced us — adopt + recompute scheme) and routine updates.
                    applyCSS(e.newValue);
                } catch (err) {
                    console.error('[ThemeLoader] Failed to update theme stylesheet:', err);
                }
            }

            if (e.key && e.key === schemeKey && e.newValue) {
                const computedScheme = computeScheme();
                window.document.documentElement.setAttribute('data-scheme', computedScheme);
                log.info('storage', 'Scheme updated via storage event', {
                    newValue: e.newValue,
                    computedScheme
                });
            }
        });

        window.matchMedia('(prefers-color-scheme: dark)').addEventListener('change', () => {
            const computedScheme = computeScheme();
            window.document.documentElement.setAttribute('data-scheme', computedScheme);
            log.info('matchMedia', 'Scheme updated via system color-scheme change', { computedScheme });
        });
    }

    // Always set the scheme, even without a sheet — the page then at least follows the
    // saved/default/system preference while waiting for the sync to land.
    const initialScheme = computeScheme();
    window.document.documentElement.setAttribute('data-scheme', initialScheme);
    log.info('themeLoader', 'Initial scheme applied', {
        scheme: initialScheme,
        savedScheme: localStorage.getItem(schemeKey),
        defaultScheme: localStorage.getItem(`${uuid}-ThemePaletteDefaultScheme`),
        systemPrefersDark: window.matchMedia('(prefers-color-scheme: dark)').matches,
        sheetLength: themeSheet ? themeSheet.length : 0
    });
};
