import { FONTS } from '@common/utils/fonts';

import { StorageThemeProvider } from '@common/components/StorageThemeProvider/StorageThemeProvider';
import { themeLoader } from '@common/components/StorageThemeProvider/theme-loader';

const BrowserThemeProvider = ({ children }: { children: React.ReactNode }) => {
    return (
        <StorageThemeProvider themeLoader={themeLoader} fonts={FONTS}>
            {children}
        </StorageThemeProvider>
    );
};

export default BrowserThemeProvider;
