import { FC, useEffect } from 'react';

import type { AppProps } from 'next/app';
import dynamic from 'next/dynamic';

// Global base styles - shared across all workspaces
import '@openfin/ui-library/core-ui/global.css';
import '@openfin/ui-library/shared/button.css';
import '@openfin/ui-library/shared/layout.css';
import '@openfin/ui-library/shared/checkbox.css';

export const SentryDynamic = dynamic(
    async () => {
        const initSentry = (await import('@common/utils/sentry')).initSentry;
        const SentryComponent = () => {
            useEffect(() => {
                initSentry();
            }, []);
            return <></>;
        };
        return SentryComponent;
    },
    { ssr: false }
);

export const CrossWindowNavigationDynamic = dynamic(
    async () => {
        const { enableCrossOFWindowNavigation } = await import('@common/utils/window-navigation');
        const CrossWindowNavigationComponent = () => {
            useEffect(() => {
                enableCrossOFWindowNavigation();
            }, []);
            return <></>;
        };
        return CrossWindowNavigationComponent;
    },
    { ssr: false }
);

const App: FC<AppProps> = ({ Component, pageProps }) => <Component {...pageProps} />;
export default App;
