import type OpenFin from '@openfin/core';

import makeGetChannelClient from '@common/utils/channels';
import { currentOFIdentity } from '@common/utils/window';

const browserWindowChannelTopic = '__browser_window__';

export const getWindowChannelId = (identity: OpenFin.Identity, prefix?: string) =>
    prefix
        ? `${prefix}-${identity.uuid}-${identity.name}`
        : `${browserWindowChannelTopic}-${identity.uuid}-${identity.name}`;

const connectionMap: Map<string, ReturnType<typeof makeGetChannelClient>> = new Map();

export interface ChannelClient extends OpenFin.ChannelClient {
    dispatch: (action: (typeof BrowserChannelAction)[keyof BrowserChannelAction], payload?: any) => Promise<any>;
}

export const getNamedChannelClient = (channelName: string): Promise<ChannelClient> => {
    if (!connectionMap.has(channelName)) {
        connectionMap.set(channelName, makeGetChannelClient(channelName));
    }
    return connectionMap.get(channelName)!();
};

export const getChannelClient = (identity: OpenFin.Identity, prefix?: string): Promise<ChannelClient> => {
    const id = getWindowChannelId(identity, prefix);
    return getNamedChannelClient(id);
};

/**
 * If the browser window is reloaded too quickly, runtime will
 * respond that the channel provider has already been created.
 * Hence, we retry a couple of times to make sure this does not occur.
 * (Should only happen in local development)
 */
export const createChannel = async (identity?: OpenFin.Identity, prefix?: string) => {
    let err: Error | undefined;
    let channel: OpenFin.ChannelProvider | undefined;

    for (let i = 0; i < 5; i++) {
        // eslint-disable-next-line no-await-in-loop
        const isCreated = await fin.InterApplicationBus.Channel.create(
            getWindowChannelId(identity ?? currentOFIdentity, prefix)
        )
            // eslint-disable-next-line no-loop-func
            .then((c) => {
                channel = c;
                return true;
            })
            // eslint-disable-next-line no-loop-func
            .catch((e) => {
                err = e;
                return false;
            });
        if (isCreated) {
            break;
        }
        // eslint-disable-next-line no-await-in-loop
        await new Promise((res) => setTimeout(res, 1000));
    }
    if (!channel) {
        throw new Error(`Failed to create channel: ${err?.message}`);
    }
    return channel;
};

let channel: Promise<OpenFin.ChannelProvider> | undefined;

export const getBrowserChannelClient = () => {
    if (!channel) {
        channel = createChannel();
    }
    return channel;
};

let viewThemeChannel: Promise<OpenFin.ChannelProvider> | undefined;
export const getViewThemeChannelClient = async () => {
    if (!viewThemeChannel) {
        viewThemeChannel = createChannel(currentOFIdentity, 'theme-change-listener');
    }
    return viewThemeChannel;
};

export interface AddToChannelRequest {
    newChannelId: string;
    selectedViews: OpenFin.Identity[];
}

/**
 * These actions are used to handle functionality activated by user in the UI (e.g. context menu)
 * and hence show dialogs, indicators etc.
 * Not to be confused with attached pages actions, which are for API use.
 */

enum GeneralBrowserChannelActions {
    CloseBrowserWindow = 'close-browser-window',
    QuitPlatform = 'quit-platform',
    ClosePage = 'close-page',
    AddToChannel = 'add-to-channel',
    RemoveFromChannel = 'remove-from-channel',
    OpenSaveModalInternal = 'open-save-modal-internal',
    DuplicatePage = 'duplicate-page',
    SetSelectedScheme = 'set-selected-scheme',
    ShowBrowserIndicator = 'show-browser-indicator',
    SetSelectedLanguage = 'set-selected-language',
    RefreshBookmarksInternal = 'refresh-bookmarks', // Enterprise
    GetLayoutsWithSelectedViewsInternal = 'get-layouts-with-selected-views', // Enterprise
    FocusAndExpandSearchInternal = 'focus-and-expand-search' // Enterprise
}

/**
 * All of the remote procedures that can be called in the
 * platform window's address space regarding attached pages.
 */
export enum PageChannelAction {
    GetPages = 'get-pages',
    GetActivePageForWindow = 'get-active-page-for-window',
    AttachPagesToWindow = 'attach-pages-to-window',
    DetachPagesFromWindow = 'detach-pages-from-window',
    SetActivePageForWindow = 'set-active-page-for-window',
    RenamePage = 'rename-page',
    ReorderPagesForWindow = 'reorder-pages-for-window',
    UpdatePageForWindow = 'update-page-for-window',
    UpdatePagesWindowOptions = 'update-pages-window-options',
    IsActivePageChanging = 'is-active-page-changing'
}

/**
 * @internal
 */
export enum EnterpriseAppDirectoryChannelAction {
    GetApps = 'get-apps',
    GetCuratedContent = 'get-curated-content',
    GetRecentlyVisited = 'get-recently-visited',
    GetSearchProviders = 'get-search-providers'
}

/**
 * @internal
 */
export enum EnterpriseBookmarkChannelAction {
    CreateBookmarkNode = 'create-bookmark-node', // Enterprise
    GetBookmarkNode = 'get-bookmark-node', // Enterprise
    SearchBookmarkNodes = 'search-bookmark-nodes', // Enterprise
    UpdateBookmarkNode = 'update-bookmark-node', // Enterprise
    DeleteBookmarkNode = 'delete-bookmark-node' // Enterprise
}

export enum CompanionDockChannelAction {
    UpdateFavoriteEntries = 'update-favorite-entries', // Enterprise
    UpdateContentMenu = 'update-content-menu', // Enterprise
    NavigateContentMenu = 'navigate-content-menu', // Enterprise
    MoreMenuCustomOptionClicked = 'more-menu-custom-option-clicked', // Enterprise
    RefreshDockCollectionMenu = 'refresh-dock-collection-menu' // Enterprise
}

/**
 * @internal
 */
export enum EnterpriseRequestModalChannelAction {
    SendUpdateVersionModalResponse = 'send-update-version-modal-response', // Enterprise
    SendIntentResolverModalResponse = 'send-intent-resolver-modal-response' // Enterprise
}

export const BrowserChannelAction = {
    ...GeneralBrowserChannelActions,
    ...PageChannelAction,
    ...CompanionDockChannelAction
};
export type BrowserChannelAction = typeof BrowserChannelAction;
