import type OpenFin from '@openfin/core';

import { getBrowserWindows } from '@common/utils/window';

import type { AttachedPage } from '@common/api/pages/shapes';
import { getBrowserChannelClient, WorkspacePlatformChannelAction } from '@common/api/protocol/workspace-platform';

import type { BrowserCreateWindowRequest, BrowserWindowFactory, BrowserWindowModule } from '../../shapes';
import {
    browserWindowPerformanceMarkAPIReturn,
    browserWindowPerformanceMarkStart,
    setupBrowserWindowShownPerformanceMark
} from '../performance';

import { getBrowserModule } from './browser-module';

export const getBrowserApi = (identity: OpenFin.ApplicationIdentity): BrowserWindowFactory => {
    const platform = fin.Platform.wrapSync(identity);

    return {
        wrapSync: (windowIdentity: OpenFin.Identity) => {
            return getBrowserModule(windowIdentity);
        },
        createWindow: async (options: BrowserCreateWindowRequest): Promise<BrowserWindowModule> => {
            const performanceMarkTitle = browserWindowPerformanceMarkStart();
            setupBrowserWindowShownPerformanceMark(performanceMarkTitle);
            await getBrowserChannelClient(identity);
            const win = await platform.createWindow(options);
            browserWindowPerformanceMarkAPIReturn(performanceMarkTitle);
            return getBrowserModule(win.identity);
        },
        getAllAttachedPages: async (): Promise<AttachedPage[]> => {
            const client = await getBrowserChannelClient(identity);
            return client.dispatch(WorkspacePlatformChannelAction.GetAllAttachedPages, undefined);
        },
        getAllWindows: async (): Promise<BrowserWindowModule[]> => {
            await getBrowserChannelClient(identity);

            const ofWindows = await getBrowserWindows();
            return ofWindows.map((w) => getBrowserModule(w.identity));
        },
        getUniquePageTitle: async (title?: string) => {
            const channel = await getBrowserChannelClient(identity);
            return channel.dispatch(WorkspacePlatformChannelAction.GetUniquePageTitle, title);
        },
        getLastFocusedWindow: async () => {
            const channel = await getBrowserChannelClient(identity);
            return channel.dispatch(WorkspacePlatformChannelAction.GetLastFocusedBrowserWindow, undefined);
        },
        getPageByViewIdentity: async (viewIdentity: OpenFin.Identity) => {
            const channel = await getBrowserChannelClient(identity);
            return channel.dispatch(WorkspacePlatformChannelAction.GetPageByViewIdentity, viewIdentity);
        }
    };
};
