import { createAsyncThunk, createSlice } from '@reduxjs/toolkit';

import { isOSWindows } from '@common/utils/os';

export interface EnvironmentRootState {
    environment: { isWindows: boolean };
}

export const getEnvironment = createAsyncThunk('environment/getEnvironment', async (): Promise<boolean> => {
    return await isOSWindows();
});

export const environmentSlice = createSlice({
    name: 'environment',
    initialState: { isWindows: true },
    reducers: {
        setEnvironment: (state, action) => {
            state.isWindows = action.payload;
        }
    },
    extraReducers: (builder) => {
        builder.addCase(getEnvironment.fulfilled, (state, action) => {
            state.isWindows = action.payload;
        });
    }
});

export const { setEnvironment } = environmentSlice.actions;

export const selectIsWindows = (state: EnvironmentRootState) => state.environment?.isWindows;

export default environmentSlice.reducer;
