import { getCachedAppInfo } from '@common/utils/application';
import { isEnvProd, isFin, isWindowDefined } from '@common/utils/env';

interface StyleOverrides {
    iconUrl: string;
}

interface HotkeyOverrides {
    toggleHomeVisibility: string;
}

export interface Overrides {
    hotkeys: HotkeyOverrides;
    style: StyleOverrides;
    browserWindowTitle: string;
    flags: {
        [key: string]: boolean;
    };
    disableRuntimeValidation: boolean;
    browserBaseUrl: string;
    disableOpenFinAnalytics: boolean;
    analyticsEndpoint: string;
    translationOverridesUrl: string;
    /**
     * WRK-4846
     * This property is internal but is being temporarily exposed for Wells Fargo.
     * It will be removed once Workspace adopts the fix in Runtime version 38.
     */
    displayViewTabDefaultIcon: boolean;
}

export async function getManifestOverrides(): Promise<Partial<Overrides>> {
    const logSource = 'getManifestOverrides';
    const { manifest, initialOptions } = (await getCachedAppInfo()) as any;
    if (
        !manifest?.platform.workspace &&
        !manifest?.platform.home &&
        !initialOptions?.workspace &&
        !initialOptions?.home
    ) {
        console.warn(`${logSource}: Missing Home development manifest overrides, using Desktop Owner Settings.`);
    }

    if (manifest?.platform.workspace) {
        console.debug(
            `${logSource}: returning settings from manifest.workspace: ${JSON.stringify(manifest?.platform.workspace)}`
        );
        return manifest?.platform.workspace;
    }

    if (manifest?.platform.home) {
        console.debug(
            `${logSource}: returning settings from manifest.home: ${JSON.stringify(manifest?.platform.home)}`
        );
        return manifest?.platform.home;
    }

    if (initialOptions?.workspace) {
        console.debug(
            `${logSource}: returning settings from initialOptions.workspace: ${JSON.stringify(
                initialOptions?.workspace
            )}`
        );
        return initialOptions?.workspace;
    }

    if (initialOptions?.home) {
        console.debug(
            `${logSource}: returning settings from initialOptions.home: ${JSON.stringify(initialOptions?.home)}`
        );
        return initialOptions?.home;
    }
    return {};
}

const getSystemAppConfig = (id: string): Promise<any> => (fin as any).System.getSystemAppConfig(id);

async function getDOSOverrides(): Promise<Partial<Overrides>> {
    const logSource = 'getDOSOverrides';
    if (!isFin) {
        console.warn(`${logSource}: the fin API was not available, returning no result`);
        return {};
    }

    try {
        // Casting fin as `any` to allow use of "secret" API
        let overrides = await getSystemAppConfig('workspace').catch((err) => {
            // Ignored
            console.debug(
                `${logSource}: customConfig entry for SystemApp workspace not available in Desktop Owner Settings. ${err?.message}`
            );
        });
        if (!overrides) {
            console.debug(
                `${logSource}: in the absence of workspace custom config falling back to check for home custom config`
            );
            // Check legacy system app config name.
            overrides = await getSystemAppConfig('home');
            console.debug(`${logSource}: home custom config retrieved`);
        }

        console.debug(`${logSource}: returning DOS settings: ${JSON.stringify(overrides)}`);

        return overrides;
    } catch (err) {
        // No DOS for Workspace, ignored.
        if (!isEnvProd) return {};

        if (err instanceof Error) {
            console.warn(
                `${logSource}: Missing Workspace Desktop Owner Settings configuration, using defaults. ${err?.message}`
            );
        } else {
            throw err;
        }
    }
    return {};
}

let overrides: Partial<Overrides> | undefined;

export async function getOverrides(): Promise<Partial<Overrides>> {
    if (overrides) {
        return overrides;
    }

    const logSource = 'getOverrides';
    if (!isFin) {
        if (isWindowDefined) {
            console.warn(`${logSource}: The Fin API was not available. Returning an empty result.`);
        }
        return {};
    }

    const [dosOverrides, manifestOverrides] = await Promise.all([getDOSOverrides(), getManifestOverrides()] as const);

    overrides = {
        ...manifestOverrides,
        ...dosOverrides,
        // In the case where either of the overrides are set to true, we will disable runtime validation.
        // Note that this differs to the default behavior of merging manifest/dos overrides (prefer desktop owner settings).
        disableRuntimeValidation: manifestOverrides.disableRuntimeValidation || dosOverrides.disableRuntimeValidation
    };

    console.debug(`${logSource}: returning final overrides: `, overrides);

    return overrides;
}
