import { initReactI18next } from 'react-i18next';

import i18next, { type Resource } from 'i18next';

import { Locale } from '@client-platform/shapes';

import chineseSimplified from '../assets/localization/chinese-simplified.json';
import chineseTraditional from '../assets/localization/chinese-traditional.json';
import english from '../assets/localization/english.json';
import german from '../assets/localization/german.json';
import japanese from '../assets/localization/japanese.json';
import korean from '../assets/localization/korean.json';
import russian from '../assets/localization/russian.json';

// manually change the language by defining lng with ISO language code
//  ie. lng: 'ko-KR'
// manually set language in the console to change language
// i.e. await fin.Workspace.WorkspacePlatform.getCurrentSync().setLanguage('ru-RU')

function initI18next(language: Locale = 'en-US') {
    i18next.use(initReactI18next).init({
        lng: language,
        fallbackLng: 'en-US',
        resources: {
            'en-US': { translation: english },
            'ja-JP': { translation: japanese },
            'zh-CN': { translation: chineseSimplified },
            'ko-KR': { translation: korean },
            'ru-RU': { translation: russian },
            'de-DE': { translation: german },
            'zh-Hant': { translation: chineseTraditional }
        },
        interpolation: { escapeValue: false }
    });
}

export const setLanguageInI18next = (locale: Locale) => {
    i18next.changeLanguage(locale);
};

const t = i18next.t;

export { initI18next, i18next, t, type Resource };
export { useTranslation } from 'react-i18next';
