import type OpenFin from '@openfin/core';

import { getLayoutWithSingleView } from '@common/utils/layout';
import { currentOFIdentity, getOFWindow, isBrowserWindow } from '@common/utils/window';

import { makePage } from '@common/api/pages';

import { getCurrentSync } from '@client-platform/api';
import { getIsEnterprisePlatform } from '@client-platform/init/enterprise';

import { getEnterpriseLandingUrl } from './browser-base-url';
import { isEnterpriseBrowser } from './enterpriseBrowser';

interface LandingPageUrls {
    newPageUrl: string | false;
    newTabUrl: string | false;
}

export const getLandingPageUrls = async (
    winIdentity: OpenFin.Identity = currentOFIdentity
): Promise<LandingPageUrls> => {
    const { workspacePlatform } = await getOFWindow(winIdentity).getOptions();
    const newPageUrl = workspacePlatform?.newPageUrl;
    const newTabUrl = workspacePlatform?.newTabUrl;
    return { newPageUrl, newTabUrl };
};

export const checkHasNewTabUrl = async (): Promise<boolean> => {
    const { newTabUrl } = await getLandingPageUrls();
    return !!newTabUrl;
};

export const getNewLandingTabViewOptions = async (
    target: OpenFin.Identity
): Promise<OpenFin.PlatformViewCreationOptions> => {
    const { newTabUrl } = await getLandingPageUrls(target);
    if (!newTabUrl) {
        throw new Error('Trying to create a new page without a newTabUrl set');
    }
    return { url: newTabUrl, target, title: 'New Tab' } as OpenFin.PlatformViewCreationOptions;
};

/**
 * Temporary help to generate a new tab layout.
 */
const getNewLandingPageConfig = async (title: string, winIdentity: OpenFin.Identity = currentOFIdentity) => {
    const { newPageUrl } = await getLandingPageUrls(winIdentity);
    if (!newPageUrl) {
        throw new Error('Trying to create a new page without a newPageUrl set');
    }
    return getLayoutWithSingleView(title, newPageUrl, winIdentity);
};

/**
 * Makes a new landing page.
 *
 * If winIdentity is specified, it uses the newPageUrl defined by the browser window options.
 * Otherwise, if the platform is Enterprise, it will use the landing page URL.
 */
export const makeNewLandingPage = async (winIdentity: OpenFin.Identity = currentOFIdentity) => {
    const isEnterprise = (await isEnterpriseBrowser(winIdentity)) || getIsEnterprisePlatform();
    // For Enterprise, view name will be used so we can leave this undefined
    const pageTitle = isEnterprise ? null : await getCurrentSync().Browser.getUniquePageTitle();

    let config: OpenFin.LayoutOptions;
    if (winIdentity && (await isBrowserWindow(winIdentity))) {
        config = await getNewLandingPageConfig(pageTitle, winIdentity);
    } else if (isEnterprise) {
        const landingPageUrl = await getEnterpriseLandingUrl();
        config = await getLayoutWithSingleView(pageTitle, landingPageUrl);
    }

    if (isEnterprise) {
        config.settings = config.settings ?? {};
        config.dimensions = config.dimensions ?? {};

        config.settings.reorderEnabled = true;
    }

    const page = await makePage(pageTitle, config);

    if (isEnterprise) {
        page.hasUnsavedChanges = false;
    }

    return page;
};
