import type OpenFin from '@openfin/core';

const interopTopic = '__interop_events__';

export enum InteropEventType {
    JoinedContextGroup = 'joined-context-group',
    RemovedFromContextGroup = 'removed-from-context-group'
}

type InteropEventPayload<E extends InteropEventType> = {
    [InteropEventType.JoinedContextGroup]: { viewIdentity: OpenFin.Identity; contextGroupId: string };
    [InteropEventType.RemovedFromContextGroup]: { viewIdentity: OpenFin.Identity };
}[E];

export type InteropListener<EventType extends InteropEventType> = (payload: InteropEventPayload<EventType>) => void;

const getInteropEventTopic = (eventName: InteropEventType) => `${interopTopic}:${eventName}`;

const emitInteropEvent = async <EventType extends InteropEventType>(
    eventType: EventType,
    payload: InteropEventPayload<EventType>
) => {
    return fin.InterApplicationBus.publish(getInteropEventTopic(eventType), payload);
};

/**
 * Returns contextGroup data.
 * @returns Promise<ContextGroup[]>
 */
export function getContextGroups(): Promise<OpenFin.ContextGroupInfo[]> {
    return fin.me.interop.getContextGroups();
}

export const joinContextGroup = async (viewIdentity: OpenFin.Identity, contextGroupId: string) => {
    await fin.me.interop.joinContextGroup(contextGroupId, viewIdentity);
    emitInteropEvent(InteropEventType.JoinedContextGroup, { viewIdentity, contextGroupId });
};

export const removeFromGroup = async (viewIdentity: OpenFin.Identity) => {
    await fin.me.interop.removeFromContextGroup(viewIdentity);
    emitInteropEvent(InteropEventType.RemovedFromContextGroup, { viewIdentity });
};

export async function getViewContextGroupId(viewIdentity: OpenFin.Identity): Promise<string | null | undefined> {
    const options = await fin.View.wrapSync(viewIdentity).getOptions();
    return options.interop?.currentContextGroup;
}

/**
 * Listen for interop events.
 * @param event the interop event to listen for.
 * @param listener the function to call when the event occurs.
 */
export const addInteropListener = <Event extends InteropEventType>(event: Event, listener: InteropListener<Event>) =>
    fin.InterApplicationBus.subscribe({ uuid: '*' }, getInteropEventTopic(event), listener);
