import { useSyncExternalStore } from 'react';

const subscribe = (callback: MutationCallback) => {
    const observer = new MutationObserver(callback);
    observer.observe(document.documentElement, {
        attributes: true,
        attributeFilter: ['data-scheme']
    });
    return () => observer.disconnect();
};

// Default scheme is dark, so dark is the correct guess whenever the
// data-scheme attribute is absent (and for the build-time/server snapshot, where
// the user's scheme cannot be known). A wrong guess is recoverable — it costs a
// hydration re-render for non-dark users — but defaulting to light meant the
// majority dark-scheme launches always paid that cost.
const getSnapshot = (): 'light' | 'dark' =>
    (document.documentElement.getAttribute('data-scheme') ?? 'dark') as 'light' | 'dark';

const getServerSnapshot = () => 'dark';

/**
 * A hook that tracks the 'data-scheme' attribute on the <html> element.
 *
 * The 'data-scheme' attribute is set by the theme-loader.ts script, and is used to track the current theme.
 */
export function useDocumentScheme(): 'light' | 'dark' {
    return useSyncExternalStore(subscribe, getSnapshot, getServerSnapshot) as 'light' | 'dark';
}
