import type OpenFin from '@openfin/core';

import { HTMLElementWithAria } from '@common/utils/a11y';
import { getViewNameFromTabId } from '@common/utils/layout';

/**
 * For clicks within a tab hat, returns the name of the attached view.
 * Returns `null` if click is not within a tab hat.
 */
export const getViewNameFromClickEvent = (event: MouseEvent): string => {
    const tabHat = (event.target as Element).closest('.lm_tab');
    // id.startsWith is a sanity check, but this should always be there in Platforms.
    if (!tabHat || !tabHat.id.startsWith('tab-')) {
        return null;
    }
    return getViewNameFromTabId(tabHat.id);
};

export function addViewTabGroupEventListener(
    tabGroup: HTMLElement,
    isPageLocked: boolean,
    shouldRemoveListener = false
): void {
    if (shouldRemoveListener) tabGroup.removeEventListener('keyup', keyUpHandler);
    function keyUpHandler(e: KeyboardEvent) {
        const tabs = tabGroup.querySelectorAll('.lm_tab');
        const addViewButton: HTMLElement = tabGroup?.querySelector('.newTabButton');

        let activeNodeIndexFallback: number;
        const focusableNodes: HTMLElement[] = [];

        if (isPageLocked) {
            // If Page locked we only want focusableNodes to be the tabs
            tabs.forEach((t: HTMLElement, i) => {
                focusableNodes.push(t);
                if (t.classList.contains('lm_active')) {
                    activeNodeIndexFallback = i;
                }
            });
        } else {
            // If Page is unlocked, then populate focusableNodes with correct elemenets (view tabs, their close buttons, and the new tab button)
            tabs.forEach((t: HTMLElement) => {
                const closeBtn: HTMLElement = t.querySelector('.lm_close_tab');
                focusableNodes.push(t, closeBtn);
                if (t.classList.contains('lm_active')) {
                    activeNodeIndexFallback = focusableNodes.length - 2;
                }
            });
            focusableNodes.push(addViewButton);
        }

        // Find the activeNode, we use dataset.activeNode to track which node is selected.
        // If there isn't one then we set the active node to the active view tab
        let activeNodeIndex = focusableNodes.indexOf(focusableNodes.find((elem) => elem.dataset.activeNode === 'true'));
        if (activeNodeIndex === -1) {
            activeNodeIndex = activeNodeIndexFallback;
        }

        if (e.key === 'ArrowLeft') {
            e.preventDefault();
            const newIndex = activeNodeIndex - 1 < 0 ? focusableNodes.length - 1 : activeNodeIndex - 1;
            moveFocusToNewNode(focusableNodes, newIndex, activeNodeIndex);
            activeNodeIndex = newIndex;
            return;
        }
        if (e.key === 'ArrowRight') {
            e.preventDefault();
            const newIndex = activeNodeIndex + 1 > focusableNodes.length - 1 ? 0 : activeNodeIndex + 1;
            moveFocusToNewNode(focusableNodes, newIndex, activeNodeIndex);
            activeNodeIndex = newIndex;
            return;
        }
    }

    /**
     * We need to track if an event listener has been added to the tab group so that we don't add multiple listeners to the same tabGroup.
     */
    if (tabGroup && tabGroup.dataset.hasEventListener !== 'true') {
        tabGroup.addEventListener<'keyup'>('keyup', keyUpHandler);
        tabGroup.dataset.hasEventListener = 'true';
    }
}

function moveFocusToNewNode(nodeArray: HTMLElement[], newNode: number, oldNode: number) {
    nodeArray[newNode].focus();
    nodeArray[newNode].setAttribute('aria-selected', 'true');
    nodeArray[newNode].dataset.activeNode = 'true';
    nodeArray[oldNode].setAttribute('aria-selected', 'false');
    nodeArray[oldNode].dataset.activeNode = 'false';
}

export const getViewUrl = async (viewIdentity: OpenFin.Identity): Promise<string> => {
    const view = fin.View.wrapSync(viewIdentity);
    return view
        .getInfo()
        .then((info) => info.url)
        .catch(() => '');
};

export function getViewTabHat(viewName: string, containerRef?: HTMLElement): HTMLElementWithAria {
    return containerRef
        ? (containerRef.querySelector(`li[id="tab-${viewName}"]`) as HTMLElementWithAria)
        : (document.querySelector(`li[id="tab-${viewName}"]`) as HTMLElementWithAria);
}
