import Router, { NextRouter, withRouter as nextWithRouter } from 'next/router';

import type PageRoute from '@common/utils/route';

import { getRouterZone, getRouteWithoutZone } from './base';

/**
 * All router events.
 */
export enum RouterEvent {
    RouteChangeComplete = 'routeChangeComplete'
}

const routerReady = new Promise<void>((res) => Router.ready(res));

/**
 * Used to get the router globally.
 */
async function getRouter() {
    await routerReady;
    return Router;
}

/**
 * React hook for components that want to use router.
 * Underlying component will be rerendered when the routing of the current page changes.
 */
export const withRouter = nextWithRouter;

/**
 * The type of router.
 */
export type Router = NextRouter;

/**
 * Prefetch a route.
 * @param route the route to prefetch.
 */
export async function prefetch(route: PageRoute) {
    const router = await getRouter();
    const routeWithoutZone = getRouteWithoutZone(route);
    return router.prefetch(routeWithoutZone, routeWithoutZone);
}

/**
 * Navigate to another route.
 * @param route the route to navigate to.
 */
export async function navigate(route: PageRoute | string) {
    const router = await getRouter();
    const routeWithoutZone = getRouteWithoutZone(route);
    return router.push(routeWithoutZone, routeWithoutZone, { shallow: route.startsWith(getRouterZone()) });
}

/**
 * Listen for a router event.
 * @param event the event to listen for.
 * @param listener the listener to call when the event occurs.
 */
export async function addRouterListener(event: RouterEvent, listener: (...args: any[]) => any) {
    const router = await getRouter();
    router.events.on(event, listener);
}

/**
 * Stop listening for a router event.
 * @param event the event to stop listening for.
 * @param listener the listener to remove.
 */
export async function removeRouterListener(event: RouterEvent, listener: (...args: any[]) => any) {
    const router = await getRouter();
    router.events.off(event, listener);
}

/**
 * Navigate the back a route.
 */
export async function navigateBack() {
    const router = await getRouter();
    return router.back();
}
