import { useEffect, useRef } from 'react';

import { registerDeferShow, setCanShow } from '@common/utils/defer-show';
import { log } from '@common/utils/logger';

/**
 * This hook prevents the current window from being shown until
 * the component in which called this hook is ready.
 *
 * The component that called this hook can designate that they are ready by
 * calling the function returned by this hook.
 *
 * If there are multiple components in which are calling this hook, the window
 * will not be shown until all of the components are ready.
 *
 * @returns a function that should be called when the component is ready to auto show.
 */
export const useDeferShow = () => {
    log.debug('useDeferShow: Hook called');
    const canShowRef = useRef(true);
    const setCanShowRef = useRef<((bool: boolean) => void) | undefined>(undefined);

    if (!setCanShowRef.current) {
        log.debug('useDeferShow: Creating new setCanShow function');
        setCanShowRef.current = (bool) => {
            log.debug('useDeferShow: setCanShow called', { bool, previousValue: canShowRef.current });
            if (canShowRef.current !== bool) {
                canShowRef.current = bool;
                setCanShow(bool);
                log.debug('useDeferShow: canShow state updated', bool);
            }
        };
        setCanShowRef.current(false);
        log.debug('useDeferShow: Registering defer show and setting initial canShow to false');
        registerDeferShow();
    }

    useEffect(
        () => () => {
            log.debug('useDeferShow: Cleanup - setting canShow to true');
            setCanShowRef.current?.(true);
        },
        []
    );

    return setCanShowRef.current;
};
